INSERT INTO `zz_coa_zhcn_item_desc_map` (`src`, `dst`) VALUES
    ('\nA Cosmetic Weapon set meant to be used with Transmogrification. You can see what they look like in the Vanity Collection.', '\n一套用于幻化的装饰性武器组合。你可以在幻化收藏中查看它们的样子。'),
    ('#1. Point the sharp end at your enemies.', '#1. 把锋利的一端对准敌人。'),
    ('#2. Using your axe for cutting wood dulls the edge.', '#2. 用斧头砍柴会磨损刃口。'),
    ('#3. Swing Wildly until there is nothing left to swing at.', '#3. 一直乱砍，直到没东西可砍为止。'),
    ('#4. Large pockets are ideal.', '第 4 号。大口袋最理想。'),
    ('#5. Make sure to keep the tip of your Polearm sharp.', '#5. 务必让长柄武器的尖端保持锋利。'),
    ('#6. First rule of Brawl Club. Don\'t tell anyone about Brawl Club.', '#6. 斗殴俱乐部的第一条规则。别跟任何人提起斗殴俱乐部。'),
    ('#7. Always keep at least one eye open.', '#7. 永远至少睁一只眼。'),
    ('\'N.P\' is engraved on the inner band.', '内圈刻着「N.P」字样。'),
    ('\'Stout\' doesn\'t even begin to describe this beer.', '「醇厚」都远远不足以形容这款啤酒。'),
    ('\'slike a wee angry bullet wit\' teeth, son.', '就像一颗长牙的小炮弹，孩子。'),
    ('...and they eat puppies!', '……而且它们还吃小狗！'),
    ('...there\'s nothing here!', '……这里什么都没有！'),
    ('...they\'re just chopped up bits of silithid.', '……这些只是切碎的异种虫碎块。'),
    ('100% More Chilling!', '寒冷程度提升 100%！'),
    ('200 gold. Your cut of the reward for freeing Prince Nadun.', '200 金币。你解救纳顿王子所得的报酬。'),
    ('98% more Holy than the previous edition', '比上一版神圣 98%'),
    ('<Although this pendant holds no sentimental value for you, it might for Thariel, Elydna\'s brother.>', '<虽然这枚吊坠对你没有纪念价值，但对伊莉德娜的兄弟萨里尔或许有。>'),
    ('A Brewmaster\'s tool for unlocking particularly hardy keg taps.', '酿酒大师用来撬开格外坚固的酒桶塞的工具。'),
    ('A Commander Dirken\'s ring with the emblem of SI:7.', '一枚刻有军情七处徽记的德肯指挥官戒指。'),
    ('A Commendation for Reaching the 6th Prestige', '达到第 6 级尊崇的嘉奖令'),
    ('A Commendation for Reaching the 8th Prestige', '达到第 8 级尊崇的嘉奖令'),
    ('A Commendation for overcoming Felforged trials and challenges.\nYou earn 1 Legion Crest for each unique challenge you complete per tier.', '一份通过邪铸试炼与挑战的嘉奖。\n你每档完成一个独特挑战即可获得 1 枚军团纹章。'),
    ('A Commendation for reaching the 7th Prestige', '达到第 7 级尊崇的嘉奖令'),
    ('A Cosmetic Weapon set that contains a Bow and an Arrow Incarnation. \n\nIt is meant to be used with Transmogrification. You can see what Cosmetic Sets look like in the Vanity Collection. These can be obtained from other players, the auctionhouse, or the Ascension shop.', '一套外观武器，包含一把弓与一个箭矢形态。\n\n用于幻化。你可以在幻化收藏中查看外观套装的样子。可从其他玩家、拍卖行或飞升商城获得。'),
    ('A Cosmetic set for Transmogrification. You can see what Cosmetic Sets look like in the Vanity Collection. These can be obtained from other players, the auctionhouse, or the Ascension shop.', '一套用于幻化的外观套装。你可以在幻化收藏中查看外观套装的样子。它们可从其他玩家、拍卖行或飞升商城获得。'),
    ('A Cosmetic set meant to be used with Transmogrification. You can see what Cosmetic Sets look like in the Vanity Collection. These can be obtained from other players, the auctionhouse, or the Ascension shop.\n\nThis set has a couple additional transmog options. Make sure to tryout the different combinations and see what cool looks you can discover!', '用于幻化的外观套装。你可以在幻化收藏中查看外观套装的样子。可从其他玩家、拍卖行或飞升商城获得。\n\n此套装还有若干额外的幻化选项。务必尝试不同的组合，看看能发现怎样的酷炫造型！'),
    ('A Ethereal Box containing random cosmetic items from the Ethereal Bazaar! Feeling lucky?', '一个装着虚灵集市随机幻化物品的虚灵宝箱！想试试运气吗？'),
    ('A Gargoyle flies into the area and bombards the target with Nature damage modified by the Death Knight\'s attack power.  Persists for 77d.', '一只石像鬼飞抵该区域，以受死亡骑士攻击强度加成的自然伤害轰击目标。  持续 77d。'),
    ('A Shaman\'s blessing is elementary.', '萨满的祝福是基本的。'),
    ('A Tiffany Cartier original.', '蒂芙尼·卡地亚原版。'),
    ('A bag of 5 gold.  For those who think they can dress themselves for the holidays.', '一袋 5 金币。给那些自以为能把自己打扮好过节的人。'),
    ('A bag of things found in the Manastorm.', '一袋在 Manastorm 里找到的东西。'),
    ('A balanced combat stance that increases the armor penetration of all of your attacks.', '一种均衡的战斗姿态，可提高你所有攻击的护甲穿透。'),
    ('A ball of oily blackness with smoke emanating from it.', '一团冒着烟的黑油球。'),
    ('A barbed whip, designed to maximize pain and bleeding with every strike. Perfect for extracting confessions from the enemy', '一根带刺的长鞭，设计上让每一次抽击都最大化痛苦与流血。用来逼敌人招供再合适不过'),
    ('A basic stone hammer, suitable for breaking bones.', '一把适合砸断骨头的基本石锤。'),
    ('A battered patrol report. Pages are missing, but key notes remain.', '一份残破的巡逻报告。缺了几页，但要点仍在。'),
    ('A beautiful poem engraved in jade by a scribe of great skill.', '由极富技艺的抄写员刻在玉石上的一首优美诗篇。'),
    ('A beautiful, but inert, piece of amber.', '一块美丽但无活性的琥珀。'),
    ('A bit mangy... but it\'s softer than the boar hides.', '有点脏兮兮的……但比野猪皮更柔软。'),
    ('A bit oversized.', '有点偏大。'),
    ('A black, cottony clump that fizzles in your hands.', '一团在你手里嘶嘶作响的黑色棉絮状物。'),
    ('A blackened, shriveled husk that nonetheless still throbs with a strange electric current.', '一具发黑干瘪的残骸，却仍颤动着奇异的电流。'),
    ('A blessed document sealed with holy light.', '一份被圣光封印的祝福文书。'),
    ('A blessed document that emanates holy light, inscribed with vows of divine service.', '一份散发圣光、写有神圣侍奉誓言的祝福文书。'),
    ('A blessed mandate bearing the seal of the vanquishers, radiating with righteous power.', '一份盖有征服者印章的受祝任命书，散发着正义之力。'),
    ('A blessed mandate that burns with righteous fire, its holy script designed to strike fear into the hearts of the corrupt.', '一份燃烧着正义之火的受祝任命书，其神圣文字旨在让腐化者的心中充满恐惧。'),
    ('A blessed tome filled with the words of the Argent\'s Dawn\'s wisest.', '一本祝福典籍，满载银色黎明最智者的话语。'),
    ('A blood-stained scroll that pulses with dark magic, reeking of iron and forbidden power.', '一卷血迹斑斑的卷轴，脉动着黑暗魔法，散发着铁锈与禁忌之力。'),
    ('A bloody remnant of the eye from a Beholder, summoned and mutilated by a warlock of dark talents.', '一隻被黑暗天赋的术士召唤并残害的眼魔眼睛的血腥残片。'),
    ('A bolt of thick, high-quality silk. It would be wasted in goblin hands.', '一匹厚实的高品质丝绸。落在哥布林手里就浪费了。'),
    ('A bone from a Vrykul pilgrim who journeyed from distant realms, before the sea transformed the region into an archipelago. For centuries, the Vrykul gathered to honor the heroes who vanquished the beast and etched its remains into the mountainside. They never fathomed that their victory was but a pyrrhic triumph.', '一块维库朝圣者的骨头，他来自遥远的国度，彼时大海尚未将此地化作群岛。数百年来，维库人齐聚于此，纪念击败野兽的英雄，并将其遗骸刻入山壁。他们从未想到，那场胜利不过是一场惨胜。'),
    ('A bone partially eroded by the acidic saliva of a certain carnivorous plant. A sad end for one who sought joy at the faire, only to meet their end in the invertebrate jaws of an abomination born from goblin negligence.', '一根被某种食肉植物的酸性唾液部分腐蚀的骨头。某个想在集市寻欢作乐的人就这样悲惨收场，最终死于由地精疏忽催生的畸变体的无脊椎巨口之中。'),
    ('A bone-bound codex that chills the air around it, its pages whispering with the voices of the departed.', '一本骨装典籍，使周围的空气变冷，书页低语着逝者的声音。'),
    ('A book detailing a mythical relic.', '一本详述某件神话遗物的书。'),
    ('A book of holy spells and blessings.', '一本圣光法术与祝福之书。'),
    ('A bow, made of the sturdiest materials.', '一把用最坚固材料制成的弓。'),
    ('A box full of bottles of Wiltedsong alcohol. You recognize the bottles well because they are the same ones you usually see at the Azzar Faire.', '一箱装满了凋零之歌酒的瓶子。你一眼就认出这些瓶子，正是你常在阿扎尔集市见到的那种。'),
    ('A breathtaking painting, commissioned by the Temple of the Jade Serpent.', '一幅令人叹为观止的画作，受玉蛇神殿委托创作。'),
    ('A bright torch used to reveal evil-doers.', '一把用于揭露恶徒的明亮火炬。'),
    ('A brutal pit lord and servant of Mannoroth the Destructor, Magtheridon found his way to Draenor after its cataclysm. With the clans in disarray, and most killed in the disaster, Magtheridon was quick to show his power, and rallied the surviving orcs under', '一名残暴的深渊领主，毁灭者玛诺洛斯的仆从，玛瑟里顿在德拉诺灾变后找到了通往该地的路。当时各氏族一片混乱、多数人在灾难中丧生，玛瑟里顿迅速展露力量，将幸存的兽人聚拢于麾下'),
    ('A bundle full of interactive Markers for raiding!', '一整套用于团队副本的交互标记！'),
    ('A bundle of cooking ingredients for the cooking school.', '一捆给烹饪学校用的烹饪材料。'),
    ('A bundle of scrawled text, sinister diagrams, and packets of spores.', '一捆潦草文字、邪恶图解和几包孢子。'),
    ('A bundle of stolen minor healing potions.', '一扎偷来的次级治疗药水。'),
    ('A cache comprising of multiple heirloom items which also provide an Experience Boost to you.\nContains x3 Heirloom Weapon Token\nContains x2 Discerning Eye of the Beast\nContains x1 Mystical Vest of Elements\nContains x1 Mystical Pauldrons of Elements', '一个包含多件传家宝的宝箱，同时为你提供经验加成。\n包含 x3 传家宝武器代币\n包含 x2 野兽的犀利之眼\n包含 x1 元素神秘外衣\n包含 x1 元素神秘护肩'),
    ('A cache comprising of multiple heirloom items which also provide an Experience Boost to you.\nContains x3 Heirloom Weapon Token\nContains x2 Discerning Eye of the Beast\nContains x1 Preened Ironfeather Breastplate\nContains x1 Preened Ironfeather Shoulders', '一个包含多件传家宝的宝箱，同时为你提供经验加成。\n包含 x3 传家宝武器代币\n包含 x2 野兽的犀利之眼\n包含 x1 精致的铁羽胸甲\n包含 x1 精致的铁羽护肩'),
    ('A cache comprising of multiple heirloom items which also provide an Experience Boost to you.\nContains x3 Heirloom Weapon Token\nContains x2 Discerning Eye of the Beast\nContains x1 Tattered Dreadmist Robe\nContains x1 Tattered Dreadmist Mantle', '一个包含多件传家宝的宝箱，同时为你提供经验加成。\n包含 x3 传家宝武器代币\n包含 x2 野兽的犀利之眼\n包含 x1 破烂的恐惧迷雾长袍\n包含 x1 破烂的恐惧迷雾衬肩'),
    ('A cache comprising of multiple heirloom items which also provide an Experience Boost to you.\nContains x3 Heirloom Weapon Token\nContains x2 Swift Hand of Justice\nContains x1 Champion\'s Deathdealer Breastplate\nContains x1 Champion Herod\'s Shoulder', '一个包含多件传家宝的宝箱，同时为你提供经验加成。\n包含 x3 传家宝武器代币\n包含 x2 迅捷正义之手\n包含 x1 斗士的死亡商人胸甲\n包含 x1 斗士的赫洛德护肩'),
    ('A cache comprising of multiple heirloom items which also provide an Experience Boost to you.\nContains x3 Heirloom Weapon Token\nContains x2 Swift Hand of Justice\nContains x1 Polished Breastplate of Might\nContains x1 Polished Spaulders of Might', '一个包含多件传家宝的宝箱，同时为你提供经验加成。\n包含 x3 传家宝武器代币\n包含 x2 迅捷正义之手\n包含 x1 打磨的力量胸甲\n包含 x1 打磨的力量护肩'),
    ('A cache comprising of multiple heirloom items which also provide an Experience Boost to you.\nContains x3 Heirloom Weapon Token\nContains x2 Swift Hand of Justice\nContains x1 Polished Spaulders of Valor\nContains x1 Polished Breastplate of Valor', '一个包含多件传家宝的宝箱，同时为你提供经验加成。\n包含 x3 传家宝武器代币\n包含 x2 迅捷正义之手\n包含 x1 打磨的勇气护肩\n包含 x1 打磨的勇气胸甲'),
    ('A cache comprising of multiple heirloom items which also provide an Experience Boost to you.\nContains x3 Heirloom Weapon Token\nContains x2 Swift Hand of Justice\nContains x1 Stained Shadowcraft Tunic\nContains x1 Stained Shadowcraft Spaulders', '一个包含多件传家宝的宝箱，同时为你提供经验加成。\n包含 x3 传家宝武器代币\n包含 x2 迅捷正义之手\n包含 x1 污渍暗雾外衣\n包含 x1 污渍暗雾护肩'),
    ('A carefully crated artifact, restored from Archaeology fragments found in Pandaria. The archaeologists at the Seat of Knowledge will be very interested in this.', '一件精心装箱的文物，由潘达利亚出土的考古碎片修复而成。知识之座的考古学家会对此非常感兴趣。'),
    ('A charm packed with marrow vitality.', '一枚充满骨髓活力的护符。'),
    ('A charm packed with the mana of dead mages.', '一个盛满了死去法师法力的护符。'),
    ('A charred tome still warm to the touch, containing fire secrets.', '一本触手仍温热的焦黑典籍，记载着火焰的秘密。'),
    ('A charred tome still warm to the touch, flickering with ember light.', '一本触手仍温热、闪烁着余烬之光的焦黑典籍。'),
    ('A charred volume chronicling centuries of dark studies.', '一卷记述了数百年黑暗研究的焦黑书册。'),
    ('A cherished painting by Del Gahrron\'s daughter.', '德尔·加隆之女的一幅珍爱画作。'),
    ('A chest with a broken lock. Only a couple of coins remain inside. A few more seem to have slipped from the thief\'s pocket and now decorate the stone floor.', '一只锁已损坏的箱子。里面只剩几枚硬币。还有几枚似乎从窃贼口袋里滑落，如今点缀在石板地面上。'),
    ('A clay tablet inscribed with protective wards of the Earthmother.', '一块刻有大地母亲守护结界泥板。'),
    ('A clean, fresh fish from Dandred\'s Fold.', '来自丹德雷德农场的干净鲜鱼。'),
    ('A cloak made from the former Lord of Blackrock own scales.', '用黑石前主人自己的鳞片制成的斗篷。'),
    ('A cloudy, swirling orb that clings tightly to the palm of your hand.', '一颗浑浊翻搅的球体，紧紧吸附在你的掌心。'),
    ('A collection of ancient troll tales and legends.', '一部古老的巨魔传说与故事集。'),
    ('A collection of mysterious and powerful alchemical concoctions.', '一系列神秘而强效的炼金调制品。'),
    ('A collection of notes, reagents, and small holy charms.', '一整套笔记、材料和小型圣物护符。'),
    ('A collection of the filthiest limericks you\'ve ever laid eyes on.', '一部你见过的最下流的打油诗集。'),
    ('A commission from the Temple of the Jade Serpent for a great work of art.', '玉蛇神殿为一幅伟大艺术品所下的委托。'),
    ('A complex rune that hums with energy.', '一枚脉动着能量的复杂符文。'),
    ('A concoction that is reminiscence of poison. Suspicious.', '一种令人联想到毒药的调制品。可疑。'),
    ('A conduit of electricity.', '一根电力导管。'),
    ('A copy of Trisira Selvane\'s spellbook. Kezia seems to have transcribed some of the spells improperly, but it could still be useful.', '特里西拉·瑟尔维恩法术书的抄本。凯齐娅似乎把一些法术抄错了，但仍有其用处。'),
    ('A copy of a journal written by Krelin, the Swashbuckler.', '剑客克雷林所写日记的副本。'),
    ('A corked glass jar with a copper coil in the center. It looks empty, yet holding it causes your hair to stand on end.', '一个塞着软木的玻璃罐，中央有铜线圈。它看起来是空的，但握着它却让你汗毛直立。'),
    ('A crate of stolen lesser healing draughts.', '一箱偷来的次级治疗药水。'),
    ('A crimson-bound tome that pulses rhythmically, its pages stained with dark knowledge.', '一本深红装帧的典籍，有节律地脉动着，书页上浸染着黑暗知识。'),
    ('A crimson-stained scroll that pulses rhythmically, its ink seeming to flow like liquid blood.', '一卷染血的卷轴，有节律地脉动着，墨迹仿佛液态鲜血般流动。'),
    ('A crude and brittle spike summoned by an ogre.', '一名食人魔召唤出的粗糙易碎尖刺。'),
    ('A crude scrawl depicting the dangerous reefs that surround Dragonmaw Port.', '一幅描绘龙喉港周边危险暗礁的粗劣草图。'),
    ('A crudely carved depiction of a murloc.', '一尊粗糙雕刻的鱼人像。'),
    ('A crumpled up letter.', '一封揉皱的信。'),
    ('A crusading knight will always heed this blessed horn\'s clarion call.', '征战的骑士永远会听从这神圣号角的召唤。'),
    ('A crystal bottle of exquisite design, crafted by the hands of a true artist.', '一只精雕细琢的水晶瓶，出自真正艺术家的双手。'),
    ('A crystal bottle of exquisite design, crafted by the hands of a true artist. Only a soul consumed by perfection would care for such intricate details, as Aldara does. Perhaps it is the lingering shadow of the suffocating expectations her parents cast upon her, long before they passed into memory.', '一只工艺精美的水晶瓶，出自真正艺术家之手。只有被完美主义吞噬的灵魂才会在意如此繁复的细节，阿尔达拉便是如此。或许，那不过是她父母早在离世之前、就强加于她的窒息期望所留下的残影。'),
    ('A crystalline disc engraved with a symbol of a hammer. According to legend, the dwarven hero once wore this as a belt buckle.', '一枚刻有锤子符号的水晶圆盘。据传说，那位矮人英雄曾把它当作腰带扣佩戴。'),
    ('A curiously pungent mineral.', '一种气味奇特的矿物。'),
    ('A daily reward for defeating Phil Grim.', '击败菲尔·格里姆的日常奖励。'),
    ('A damaged book detailing a lost hero of the War of the Ancients.', '一本残破的书，详述上古之战中一位失落的英雄。'),
    ('A dangerous heap of random bits of metal scrap or broken glass.', '一堆随机的金属废料或碎玻璃，很危险。'),
    ('A dangerous tome reeking of exotic toxins, with green vapors seeping from between its pages.', '一本散发着异域毒素气味的危险典籍，书页间渗出绿色雾气。'),
    ('A decent haul from the brawl pit.', '从斗殴坑里的一笔不错的收获。'),
    ('A decoded message from the rogues that infiltrated the red dragonflight!', '一条潜入红龙军团的盗贼们发来的解密讯息！'),
    ('A deep fried fish stick served on a sausage roll... MADNESS!', '一根放在香肠卷上的深炸鱼条……疯了！'),
    ('A defensive combat stance.  Decreases damage taken by  and damage caused by   Increases threat generated.', '一种防御性战斗姿态。  受到的伤害降低 ，造成的伤害降低  提高产生的威胁值。'),
    ('A delivery for Mixmaster Jasper.', '给调酒师贾斯珀的货物。'),
    ('A demonic contract that burns with green flames yet never consumes.', '一份燃烧着绿色火焰却永不燃尽的恶魔契约。'),
    ('A demonic pact wreathed in green flames, its infernal script burning the eyes of those who read it.', '一份环绕绿色火焰的恶魔契约，其上地狱文字灼烧着读者的双眼。'),
    ('A dense slab of living bark hardened by the lake shore.', '一块被湖岸硬化了的活树皮厚板。'),
    ('A depiction of rituals that took place in the Temple of Quel\'Dormir.', '一幅描绘奎尔多米尔神殿中举行仪式的图卷。'),
    ('A depiction of the fortress using primitive icons to represent essential structures.', '一张用简陋图标标示关键建筑的堡垒示意图。'),
    ('A detailed account of the Battle of Ironforge Airfield, highlighting your heroism.', '一份关于铁炉堡机场战役的详尽记述，彰显了你的英雄事迹。'),
    ('A detailed recounting of the protector\'s patrol. It makes note of a burnt farmhouse just east of Sentinel Hill - perhaps something was left behind?', '一份关于守卫巡逻的详细记录。其中提到哨兵岭以东有一座被焚毁的农舍——也许那里还留有东西？'),
    ('A detailed set of plans for Twilight\'s Hammer and Dark Iron domination of the Eastern Kingdoms.', '一份详尽的计划书，内容为暮光之锤与黑铁矮人如何统治东部王国。'),
    ('A device with a reusable parachute engineered to a paradime!', '一台配备按抛物线工程设计的可复用降落伞的装置！'),
    ('A diary written by Za\'Bor the Hunter.', '猎人扎博写的日记。'),
    ('A disease dealing  Frost damage every 3 sec and reducing the target\'s melee and ranged attack speed by  for   Caused by Icy Touch and other spells.\n\nBase damage  from attack power P*0.055*1.15}', '一种疾病，每 3 秒造成  点冰霜伤害，并使目标的近战与远程攻击速度降低 ，持续 。由冰霜之触及其他法术导致。\n\n基础伤害  来自攻击强度 P*0.055*1.15}'),
    ('A disease dealing  Shadow damage every 3 sec for   Caused by Plague Strike and other abilities.\n\nBase damage  from attack power P*0.055*1.15}', '一种疾病，每 3 秒造成  点暗影伤害，持续 。由瘟疫打击及其他技能导致。\n\n基础伤害  来自攻击强度 P*0.055*1.15}'),
    ('A disgusting fruit with pus-like ichor bursting from its leathery skin.', '一种恶心水果，脓状汁液从它革质的表皮中迸出。'),
    ('A dried, pungent fungal bloom.', '一朵干燥、气味刺鼻的菌花。'),
    ('A dull, nicked sword from battles fought generations ago.', '一柄钝了、满是缺口的剑，来自几代人之前的战斗。'),
    ('A faint dark whisper emanates from somewhere within the core.', '核心深处传出微弱的黑暗低语。'),
    ('A faint whispering can be heard from the bottle.', '能听到瓶子里传来微弱的低语。'),
    ('A feather in the hand is worth a Levitate.', '手中一根羽，胜过一次漂浮术。'),
    ('A fel-touched contract wreathed in green flames, its demonic script searing the eyes of those who read it.', '一份环绕绿色火焰的邪能契约，其恶魔文字灼烧着读者的双眼。'),
    ('A fierce attack causing  damage, modified by pet level, that your pet can use after it makes a critical attack.  Cannot be dodged, blocked or parried.', '一次凶猛的攻击，造成  点伤害（受宠物等级影响），宠物可在造成暴击后使用。  无法被躲闪、格挡或招架。'),
    ('A finely crafted blade that seems to drink in the shadows around it.', '一把工艺精良的刀，似乎会吸取周围的阴影。'),
    ('A fish with wings?  That\'s a new one.', '长翅膀的鱼？还真是新鲜。'),
    ('A fist-sized lump of ashen charcoal, warm to the touch.', '一块拳头大小、触手温热的灰炭。'),
    ('A fitting burial shroud for Helgrum.', '给赫尔格鲁姆的合身裹尸布。'),
    ('A fizzy sasparilla containing vanilla ice cream.', '加了香草冰淇淋的起泡沙士汽水。'),
    ('A flask full of liquid from a plagued water elemental.', '一瓶取自染疫水元素的液体。'),
    ('A formal letter penned by Regent Valorcall, requesting for Stromgarde to rejoin the Alliance in return for aid in retaking the keep.', '一封由摄政瓦罗卡尔撰写的正式信件，请求激流堡重归联盟，以换取夺回要塞的援助。'),
    ('A foul-smelling and fibrous weed.', '一种气味难闻的纤维杂草。'),
    ('A fowl smelling drink.', '一杯难闻的饮料。'),
    ('A fragment of memory that holds only pain.', '一段只承载痛苦的记忆碎片。'),
    ('A fragment of unknown origin, seething with ancient power.', '一块来历不明的碎片，翻涌着远古之力。'),
    ('A fragment still humming with elemental power.', '仍回荡着元素力量的碎片。'),
    ('A fresh sample of blood from the recently fallen assassin.', '一名刚倒下的刺客的新鲜血液样本。'),
    ('A friend asks for your time. A guild asks for your money.', '朋友要的是你的时间。公会要的是你的钱。'),
    ('A fur trinket, made to look like a cat.', '一件做成猫样的毛饰。'),
    ('A gift for Chabal.', '给沙巴尔的礼物。'),
    ('A gift for a lonely troll.', '给孤独巨魔的礼物。'),
    ('A gift from Snow Blossom, Destroyer of Men', '来自雪之华、灭世者的礼物。'),
    ('A gift from the Queen herself.', '女王亲自赐予的礼物。'),
    ('A gland swollen with richly colored pigments.', '一个因富含彩色素而肿胀的腺体。'),
    ('A glass lens that seems to glow brightly as you bring it near your body.', '一片玻璃透镜，靠近你的身体时似乎会明亮发光。'),
    ('A globe of restless liquid, swirling solidly within your hand.', '一颗不安分液体的球体，在你手中坚定地旋转。'),
    ('A golden scripture blessed by An\'she.', '受安瑟祝福的金色经文。'),
    ('A golden scripture that glows with warm sunlight, radiating divine healing energy.', '一部散发温暖阳光、流淌神圣治疗能量的金色经文。'),
    ('A golden scripture that radiates the warm light of dawn, its blessed parchment glowing with healing energy.', '一份散发黎明温暖光辉的金色经文，其受祝羊皮纸闪耀着治疗能量。'),
    ('A grim letter bound in black leather that seems to drain light from its surroundings and carries the scent of autumn\'s end.', '一封以黑色皮革装订的阴沉信件，似乎会吸收周围的光线，带着秋末的气息。'),
    ('A groady sack of explosive charges slathered in oil and grease.', '一个涂满油脂的脏袋子，装着爆炸物。'),
    ('A gross mishmash of different bits.', '各种碎片胡乱拼成的一团。'),
    ('A hardy flower, impossibly grown in lands where life should not endure. These resilient blooms carry the quiet strength of nature defying all odds.', '一种顽强的花，竟能在生命本不应存续之地生长。这些坚韧的花朵承载着自然无视一切逆境的力量。'),
    ('A hastily written and firmly sealed letter.', '一封写得匆忙、封得严实的信。'),
    ('A hastily written and violently sealed letter.', '一封匆匆写成、粗暴封缄的信。'),
    ('A heap of burned, mangled, crunched-up machinery.', '一堆烧毁、扭曲、压碎的机械残骸。'),
    ('A heap of disorganized journal entries.', '一堆杂乱的日志条目。'),
    ('A heap of patchwork machinery only an engineer could love.', '只有工程师才会喜欢的拼凑机械。'),
    ('A heap of steaming, superheated innards.', '一堆冒着热气的超高温内脏。'),
    ('A heavy box of well-worn grease-coated instruments.', '一箱沾满油污、磨损严重的沉重工具。'),
    ('A heavy branch torn from Thornroot at Iris Lake.', '从艾瑞斯湖的荆棘根上扯下的一根粗枝。'),
    ('A heavy piece of canvas, probably used as a blanket or shawl.', '一大块帆布，大概是当毯子或披肩用的。'),
    ('A heavy stone slab etched with glowing runes that pulse with ancient magical power.', '一块沉重的石板，上面雕刻着随古老魔法之力脉动的符文。'),
    ('A heavy, corroded battery wired sloppily to a large metal dish.', '一块用线草率接到大金属盘上的沉重腐蚀电池。'),
    ('A holy artifact crafted from lightforged iron.', '用光铸铁锻造的神圣神器。'),
    ('A holy instrument of Radiance Town, anointed to wash the faithful in emerald brilliance; half liquid, half vapor.', '光辉镇的神圣器具，涂油以翠绿光辉洗沐信徒；半为液体，半为蒸气。'),
    ('A horrible smelling slime drips from the meat. It will take days to get the stench out of your bag.', '肉上渗出气味难闻的黏液。你的背包要好几天才能散掉这股味道。'),
    ('A huge piece of meat.  This will feed dozens.', '一大块肉。这够几十个人吃。'),
    ('A hulking, unappetizing mass of pulverized flesh.', '一大团令人毫无食欲的粉碎肉块。'),
    ('A hunk of plagued spider flesh.', '一块染疫的蜘蛛肉。'),
    ('A key formed of solid blood. It doesn\'t seem like it will hold together long, you\'d best find a use for it quickly.', '一把由凝固鲜血构成的钥匙。它似乎维持不了多久，你最好尽快用掉。'),
    ('A key from the Underroof guards that unlocks the cell where they threw Glotka', '一把来自暗顶守卫的钥匙，可打开他们关押格洛特卡的牢房。'),
    ('A large and vicious-looking fish, bloated on the flesh of the dead.', '一条貌相凶恶的大鱼，被死者的血肉撑得胀满。'),
    ('A large pile of gold coins...', '一大堆金币……'),
    ('A large tail feather from one of the region\'s hawks.', '该地区某只鹰身上的一根大尾羽。'),
    ('A layer of blood coats this weapon. You\'re not sure if it was from battle, or a ritual the Bleeding Hollow uses to enchant their weapons.', '这武器上覆着一层鲜血。你无法确定它来自战斗，还是来自流血之洞用以附魔武器的仪式。'),
    ('A leather-bound compendium reeking of exotic toxins, with green vapors occasionally seeping from between its pages.', '一本散发异域毒素气味的皮面汇编，书页间偶尔渗出绿色雾气。'),
    ('A leather-bound guide marked with beast tracks of the plains.', '一本标满平原野兽足迹的皮革装订指南。'),
    ('A leather-bound guide that smells of the wild, stained with mud and marked by animal tracks.', '一本散发荒野气息的皮面指南，沾满泥污，残留着野兽的足迹。'),
    ('A lethal poison generously provided by Tabetha to aid in reaching the spirit world.', '一瓶致命毒药，由塔贝萨慷慨提供，助你抵达灵魂世界。'),
    ('A letter bearing the seal of Venture Co. There\'s no reason you can\'t read it for yourself before bringing it to Kwexle...', '一封盖有风险投资公司印章的信。在交给奎克斯勒之前，你完全可以先自己读一读……'),
    ('A light beer with a big head.', '一杯泡沫丰富的淡啤酒。'),
    ('A light heart carries you through bad Battlegrounds.', '轻松的心态能带你熬过糟糕的战场。'),
    ('A list of Kurzen officials.', '一份库尔森官员名单。'),
    ('A list of arcane ingredients and some instructions for preparation.', '一份奥术材料清单以及一些备制说明。'),
    ('A list of demonic rites, written in a deep, red ink.', '用深红色墨水写成的恶魔仪式清单。'),
    ('A little muddy.', '有点泥泞。'),
    ('A little shaken, but in good shape... all things considered.', '有点晃，但总体状况良好……算是吧。'),
    ('A lockbox that contains kill orders.', '一个装有刺杀命令的锁箱。'),
    ('A long series of praises to Queen Azshara and Matron Vashj.', '一长串对艾萨拉女王与瓦丝琪女王的赞颂。'),
    ('A long-forgotten piece of body armor.', '一件被久忘的护甲。'),
    ('A loop of seemingly ordinary ornamental chain that fills your mind with dread as it touches your flesh.', '一圈看似普通的装饰链条，触及你的肌肤时却让你心中充满恐惧。'),
    ('A lost widow\'s walking cane...I wonder what she used it for?', '一位失去丈夫的寡妇的拐杖……不知道她用来做什么？'),
    ('A lovingly written note, from a student to an old teacher.', '一名学生写给一位老教师的满怀深情的便条。'),
    ('A magically-charged cane, used for both magic and discipline.', '一根充满魔法的手杖，既用于施法也用于戒律。'),
    ('A man without a scroll, is a man without protection.', '没有卷轴的人，就是没有保护的人。'),
    ('A manifesto of sorts.', '算是一份宣言吧。'),
    ('A manuscript covered in shifting symbols that seem to writhe when observed.', '一部覆满变换符号的手稿，那些符号在被注视时似乎会扭动。'),
    ('A manuscript covered in shifting symbols that whisper dark truths.', '一部覆满不断变换的符号、低语着黑暗真相的手稿。'),
    ('A manuscript that crackles with electrical energy, thunder rumbling softly from within its pages.', '一份迸发电气能量的手稿，书页间隐约回荡着雷声。'),
    ('A massive piece of diseased bear flesh.', '一大块染病的熊肉。'),
    ('A mighty token created from the godly combination of pure evil of the necropolis and money.', '一枚由亡者之城纯粹邪恶与金钱神圣结合而成的强大代币。'),
    ('A miracle of Gnomish Design!', '侏儒设计的奇迹！'),
    ('A miracle of Goblin Design!', '地精设计的奇迹！'),
    ('A mocking attack that causes a moderate amount of threat and forces the target to focus attacks on you for   If the target is tauntable, also deals weapon damage.', '一次嘲讽攻击，产生中等量的威胁值，并迫使目标在  内集中攻击你。  若目标可被嘲讽，还会造成武器伤害。'),
    ('A modest share of the brawl winnings.', '斗殴奖金中不大的一份。'),
    ('A mollusc of exceptional size and, hopefully, flavor.', '一只特大号的软体动物，但愿它也好吃。'),
    ('A moonlit bloom sealed in polished wildwood.', '一封封在抛光野木中的月华之花的信。'),
    ('A musty, somewhat hollow taste with a hint of fish.', '带着霉味、略显空洞，还有点鱼腥。'),
    ('A mysterious letter containing the following information:', '一封神秘的信件，内含以下信息：'),
    ('A mystical scroll bound with strange herbs and marked with tribal symbols that whisper of ancient spirits.', '一卷用奇异草药束缚、印有部族符号的秘法卷轴，低语着古老灵魂。'),
    ('A name is inscribed on the back of the stone.', '石头背面刻着一个名字。'),
    ('A nature-worn parchment still bearing traces of the wild - pine needles, moss, and the scent of deep forests.', '一张被自然风化的羊皮纸，仍带着荒野痕迹——松针、苔藓与深林的气息。'),
    ('A near-perfect, goblin-manufactured knockoff of the Wonderworks original.', '一件近乎完美的地精仿制品，仿的是奇迹工坊的原版。'),
    ('A nice hefty chunk, still big enough to carry.', '一大块，还够搬得动。'),
    ('A note accompanies this egg: "The broodmother has arrived."', '一枚附言写着：「母巢已至。」的蛋。'),
    ('A note from the owner of the falcon.', '猎鹰主人留下的一张便条。'),
    ('A note reads "Use on Hellboars ONLY, not designed for use on any other creature."', '一张便条写着：「仅可用于地狱野猪，不适用于其他任何生物。」'),
    ('A page of instructions to build the Scarlet Crusade\'s ultimate weapon.', '一页建造血色十字军终极武器的说明。'),
    ('A page ripped from the Codex of Secrets.', '从秘密法典上撕下的一页。'),
    ('A palpable force booms out when the drum is struck.', '敲击战鼓时，震起一股可感的力量。'),
    ('A paper-thin leaf with razor-sharp edges.', '一片薄如纸、边缘锋利的叶子。'),
    ('A pendant marking the warriors of Malgorm Hollowhoof, tyrant of Three Totems. Only the strongest among them ever earned this distinction.', '一枚吊坠，标记着三图腾暴君玛尔戈姆·空蹄麾下的战士。只有他们中最强者才配获得这份殊荣。'),
    ('A piece of correspondence from the local lieutenant.', '当地中尉的一封往来信件。'),
    ('A piece of paper meant to provide information to the people that once lived in the town here. The true report has likely worn away long ago, and this is nothing but a lingering memory of it.', '一张纸，原本是给曾在此镇居住的人们提供信息的。真正的报告大概早已褪去，如今只剩下关于它的残存记忆。'),
    ('A piece of rock that was kicked up when Pimento stomped on the ground.', '皮门托跺地时踢起来的一块岩石。'),
    ('A piece of the Emerald Dream given to you by a strange being you found within the realm of spirits. Drawing upon its power allows you to witness memories of the past.', '一块由你在灵魂之域遇到的奇异存在交给你的翡翠梦境碎片。借助它的力量，你能见证过去的记忆。'),
    ('A pile of scrawled missives detailing Horde movements through Mulgore, Durotar, and the Barrens.', '一堆潦草的急件，详述部落穿越莫高雷、杜隆塔尔与贫瘠之地的动向。'),
    ('A pinchy little freshwater decapod crustacean.', '一只又小又扎人的淡水甲壳类。'),
    ('A plain wooden staff, used by scribes as a receptacle for inscriptions of great power.', '一根普通的木杖，被抄写员用作承载强大铭文的容器。'),
    ('A playing card with worn edges. It looks like part of an underground gambling game.', '一张边缘磨损的扑克牌，看起来像是某种地下赌博游戏的一部分。'),
    ('A polished steel tablet inscribed with protective vows, radiating an aura of unbreakable defense.', '一块刻有守护誓言的抛光钢制石板，散发着不可破防御的光环。'),
    ('A polished steel tablet inscribed with solemn vows of protection, radiating an aura of unbreakable defense.', '一块刻有庄严守护誓言的抛光钢制石板，散发着不可破防御的光环。'),
    ('A potful of perfect potatoes.', '一锅完美的土豆。'),
    ('A potion that warps your flesh to resemble a dead lieutenant of the Scarlet Crusade.', '一瓶能扭曲你的血肉、使你看起来像血色十字军已死中尉的药水。'),
    ('A pouch stitched from resilient crocolisk scale.', '用坚韧鳄鱼皮缝制的小袋。'),
    ('A powerful demonic artifact created from the skull of the orc sorcerer Gul\'dan.', '一件以兽人术士古尔丹头骨制成的强大恶魔神器。'),
    ('A powerful staff warped by the leylines.', '被地脉扭曲的强大法杖。'),
    ('A proclamation sealed with shadow, bearing the mark of the Knights of Xoroth.', '一份以暗影封印的公告，带有索洛斯骑士团的印记。'),
    ('A prototype Millhouse Manastorm made to open a path out of the Manastorm, reassembled in a way you think seems to be correct. Millhouse can easily pull those he sends into the Manastorm back out, but maybe you\'ll find another need for such a device.', '米尔豪斯·法力风暴制作的原型装置，用于打开一条离开法力风暴的通道，其拼装方式与你想的似乎一致。米尔豪斯能轻松把他送入法力风暴的人拉回来，不过你或许会发现此类装置还有别的用途。'),
    ('A proud fighter displays the ears of those he has slain in battle.', '骄傲的战士在战斗中割下敌人的耳朵挂在身上做展示。'),
    ('A pungent beverage with spicy overtones.', '带辛辣风味的刺鼻饮料。'),
    ('A putrid odor exudes from the slimy piece of meat.', '那块黏滑的肉散发出一股腐臭。'),
    ('A quick kick that interrupts spellcasting and prevents any spell in that school from being cast for', '一次快速踢击，可打断施法，并使该系法术在接下来一段时间内无法施放，持续'),
    ('A quick synopsis on those who call themselves Reapers.', '一份关于自称收割者之人的简要概述。'),
    ('A quickly-burning wooden stick.', '一根燃烧得很快的木棒。'),
    ('A ragged, filthy tiger-skin banner.', '一面破烂肮脏的虎皮旗。'),
    ('A random Darkmoon Card of Destruction.  Collect a full set to receive a reward.', '一张随机暗影暗月卡。集齐全套可获得奖励。'),
    ('A random Darkmoon Card of Mists.  Collect a full set to receive a reward.', '一张随机迷雾暗月卡。集齐全套可获得奖励。'),
    ('A random bundle of fireworks!', '一捆随机的烟花！'),
    ('A rare and mysterious flower.', '一朵稀有而神秘的花。'),
    ('A rare ink for calligraphy. It has no magical properties, but its hue is sought after by scribes for use in works on war.', '一种稀有的书法墨水。它没有魔法属性，但其色泽为抄写员用于战争论著时所追求。'),
    ('A raw elemental tome that swirls with untamed forces of nature.', '一本翻涌着狂野自然力量的原始元素典籍。'),
    ('A re-purposed laser drill, warm to the touch and humming.', '一台改装的激光钻，触手温热，嗡嗡作响。'),
    ('A reaped soul from Death\'s Door. This item persists through death.', '从死亡之门外收割来的灵魂。此物品不因死亡而丢失。'),
    ('A reaped soul from the Elemental Plateau. This item persists through death.', '一个来自元素高地的被收割的灵魂。此物品不因死亡而丢失。'),
    ('A recipe from an alchemist of the Royal Society of Apothecaries, who developed a poison capable of knocking out a bull for forty-eight hours.', '来自皇家药剂师学会一位炼金师的配方，他研制的毒药足以让一头公牛昏迷四十八小时。'),
    ('A recipe from the ancient Kaldorei Empire, preserved all these years by the strange repository. Teaches you how to bake a Miru Berry Strudel.', '一份来自古老卡多雷帝国的配方，多年来被那座奇怪的宝库保存下来。教你烘烤米鲁莓果卷。'),
    ('A reeking mass of fur, skin, and connective tissue.', '一团散发着臭气的毛皮、皮肤和结缔组织。'),
    ('A remaining piece of the Temple of Elune.', '月神殿残留的一块构件。'),
    ('A remnant from a previous generation of dwarves.', '矮人上一代遗留下来的东西。'),
    ('A repository of ancient lore, chiseled into polished granite.', '一部凿刻在抛光花岗岩上的古代传说集。'),
    ('A reward for defeating Frostclaw.', '击败霜爪的奖励。'),
    ('A ring that hums with the voices of ancient souls, occasionally summoning their spirits.', '一枚回荡着古老灵魂低语的戒指，偶尔会召唤出他们的灵魂。'),
    ('A ritual object decorated with bones and dark charms.', '一件以骨骼与黑暗护符装饰的仪式用具。'),
    ('A rough sphere carved from the native rock of Pandaria.', '用潘达利亚原生岩石雕成的粗糙球体。'),
    ('A rusted key taken from Chronicler Harvey. It should open Mordis Greychain\'s cell.', '一把从编年史家哈维身上取得的生锈钥匙。它应该能打开莫迪斯·灰链的牢房。'),
    ('A sack filled with odd bits of gristle and uncooked meat.', '一个装满奇怪软骨与生肉碎块的袋子。'),
    ('A sack of fish.', '一袋鱼。'),
    ('A sack of food, and a few reports on Coldlight Chasm and the Coldlight murlocs.', '一袋食物，外加几份关于冷光裂谷与冷光鱼人的报告。'),
    ('A sacred vow written on blessed parchment that emanates holy light and fills nearby hearts with courage.', '写在受祝羊皮纸上的神圣誓言，散发圣光，令周围人心充满勇气。'),
    ('A salt-stained diary filled with pirate musings.', '一本沾满盐渍、写满海盗遐想的日记。'),
    ('A scrap of fabric that bears Alliance colors. Perhaps additional scraps can be found on Slingtail Stickypaws.', '一块带有联盟配色的布料碎片。也许在粘爪投石者身上还能找到更多碎片。'),
    ('A scroll detailing numbers and locations of detatchments sent all over the Highlands.', '一卷详述高地各处派遣部队数量与位置的卷轴。'),
    ('A scroll marked with mystical voodoo symbols and bound with exotic feathers.', '一卷标有神秘巫毒符号、以异域羽毛捆扎的卷轴。'),
    ('A scroll that crackles with elemental energy, swirling with miniature storms, flames, and earthen tremors.', '一卷迸发元素能量的卷轴，内部盘旋着微型风暴、火焰与大地的震颤。'),
    ('A scroll that crackles with raw elemental energy, swirling with miniature tempests and flames.', '一卷迸发原始元素能量的卷轴，内部盘旋着微型的风暴与火焰。'),
    ('A scroll that seems to age and renew before your eyes, defying time itself.', '一卷在你眼前似乎会老去又更新、违抗时间本身的卷轴。'),
    ('A sealed crate of cigars.', '一箱密封的雪茄。'),
    ('A sealed letter bearing the burning mark of the Inquisition.', '一封带有异端审问会灼印的密封信件。'),
    ('A sealed message from Justicar Malric.', '来自审判者马尔里克的一封密封信。'),
    ('A sealed vial containing notes on transformative toxins.', '一只密封小瓶，内装关于转化毒素的笔记。'),
    ('A second test token for the Currency Token system', '货币代币系统的第二个测试代币'),
    ('A series of crude scrawlings, angrily drawn.', '一连串怒气冲冲画下的粗劣涂鸦。'),
    ('A set of dusty bandages that were holding Stephen Browman together.', '一套积尘的绷带，原本是用来把斯蒂芬·布朗曼绑在一起的。'),
    ('A set of dusty, crumpled notes with the stamp of The Reliquary.', '一叠盖有圣物保管会印章的积尘皱笔记。'),
    ('A set of marked dice for cheating in gambling games.', '一副用于赌局作弊的标记骰子。'),
    ('A set of parchment covered in messy scrawling that appears way too chaotic to be an ordered code.', '一叠覆满潦草字迹的羊皮纸，混乱得完全不像是有序的密码。'),
    ('A shadow-wreathed document bearing the seal of Xoroth, radiating cold darkness.', '一份暗影缠绕的文书，带有索洛斯的封印，散发着冰冷黑暗。'),
    ('A shadow-wreathed proclamation bearing the seal of Xoroth, its dark flames cold to the touch.', '一份环绕暗影的公告，盖有克索诺斯之印，其黑暗火焰触手冰凉。'),
    ('A sharpened blackthorn splinter from an ancient guardian.', '一根来自古代守卫的锋利黑刺李碎片。'),
    ('A shimmering elixir that enhances mental clarity and focus. Must be delivered quickly before its potency fades.', '一瓶闪耀的药剂，可增强思维清晰与专注。必须在其效力消退前尽快送达。'),
    ('A short length of rope, suitable for climbing.', '一小段适合攀爬的绳索。'),
    ('A short list of political prisoners within the compound.', '一份营区内政治犯的简短名单。'),
    ('A short stack of old, rusted blades.', '一小摞老旧生锈的刀刃。'),
    ('A short-range shot that deals  weapon damage and disorients the target for   Any damage caused will remove the effect.  Turns off your attack when used.', '一次短距离射击，造成  点武器伤害并使目标迷惑 ，持续 。  任何伤害都会解除该效果。  使用时将关闭你的攻击。'),
    ('A shot that deals  weapon damage and Silences the target for   Non-player victim spellcasting is also interrupted for 47d.', '一次射击，造成 点武器伤害并使目标沉默，持续  非玩家受害者的施法也会被打断，持续 47d。'),
    ('A simple beverage with a complex flavor.', '简单饮料，风味复杂。'),
    ('A simple chain, faded with age.', '一条因岁月而褪色的朴素链子。'),
    ('A simple staff carved from red pine, of all things.', '竟是一根用红松雕成的简陋法杖。'),
    ('A small amount of potent spider venom.', '少量强效的蜘蛛毒液。'),
    ('A small chest of stolen elixirs.', '一小箱偷来的药剂。'),
    ('A small crate of Draenei Archaeology fragments.', '一小箱德莱尼考古碎片。'),
    ('A small crate of Fossil Archaeology fragments.', '一小箱化石考古碎片。'),
    ('A small crate of Nerubian Archaeology fragments.', '一小箱蛛魔考古碎片。'),
    ('A small crate of Night Elf Archaeology fragments.', '一小箱暗夜精灵考古碎片。'),
    ('A small crate of Orc Archaeology fragments.', '一小箱兽人考古残片。'),
    ('A small crate of Tol\'vir Archaeology fragments.', '一小箱托维尔考古碎片。'),
    ('A small crate of Troll Archaeology fragments.', '一小箱巨魔考古碎片。'),
    ('A small crate of Vrykul Archaeology fragments.', '一小箱维库考古碎片。'),
    ('A small dagger with a worn blade, used in stealth missions.', '一把刀刃磨损的小匕首，用于潜行任务。'),
    ('A small jeweled statue.', '一尊镶嵌珠宝的小雕像。'),
    ('A small leather doll, in the shape of a crocodile.', '一个鳄鱼形状的小皮娃娃。'),
    ('A small metal brazier full of burning incense, with a handle for carrying.', '一只装满燃烧熏香的小金属炭盆，带有便于携带的提手。'),
    ('A small metal container, filled with incense and spices.', '一个小金属容器，装满了香与香料。'),
    ('A small naga statue.', '一尊小纳迦雕像。'),
    ('A small pile of musky-smelling powder.', '一小堆带麝香味的粉末。'),
    ('A small sword. One might even say... a dagger.', '一把小剑。甚至可以说是……一把匕首。'),
    ('A small vial of salt.', '一小瓶盐。'),
    ('A small, glowing rock kept wrapped up in Dinwhisker\'s inner shirt pocket.', '一块发光的小石头，一直裹在丁威斯克的内衬口袋里。'),
    ('A small, jade-colored statue.', '一尊小巧的玉色雕像。'),
    ('A small, rose-colored statue.', '一尊小巧的玫瑰色雕像。'),
    ('A small, vaguely ape-shaped statue.', '一尊小巧的、隐约像猿的雕像。'),
    ('A smoldering manuscript that radiates intense heat, with flames dancing across its scorched surface.', '一份闷燃的手稿，散发着强烈高温，火焰在其焦痕表面舞动。'),
    ('A sophisticated stove.  For a sophisticated chef.', '一台精致的炉子。为精致的厨师准备。'),
    ('A specially crafted tool for scraping hardened barnacles. Right-click to use on nearby barnacles.', '专门用来刮除硬化藤壶的特制工具。右键点击可对附近的藤壶使用。'),
    ('A spectral and wispy image of a crystal shard.', '一枚水晶碎片的幽灵般缥缈影像。'),
    ('A spiral loop of elementium that seems to chant at you when held to your ear.', '一圈螺旋状的源质，贴在耳边时似乎会对你低声吟唱。'),
    ('A splintered fragment of a larger fel core, this shard glimmers with volatile power. The demonic energy within distorts the very air around it.', '这是一块从更大的邪能核心上裂下的碎片，闪烁着不稳定之力。其中的恶魔能量扭曲了周围的空气。'),
    ('A squirmy, nasty, bitey thing.', '一个蠕动的、恶心的、会咬人的东西。'),
    ('A stack of unsent mail.', '一叠未寄出的信。'),
    ('A standard-issue necklace given to all Twilight\'s Hammer initiates in Searing Gorge.', '一条发给灼热峡谷所有暮光之锤新成员的制式项链。'),
    ('A steel tablet inscribed with protective wards that shimmer with defensive magic.', '一块刻着守护符文的钢制石板，闪烁着防御魔法的微光。'),
    ('A stolen journal written by Krelin, the Swashbuckler.', '剑客克雷林写的一本被偷走的日记。'),
    ('A stolen manual detailing closely-guarded fighting techniques of the Alliance.', '一份被窃取的手册，详述联盟严密保守的战斗技巧。'),
    ('A stone covered in glowing ancestral runes.', '一块覆满发光祖灵符文的石头。'),
    ('A stone shard, densely covered in strange etchings.', '一块布满奇异刻痕的石头碎片。'),
    ('A stone tablet carved with ancient Tauren runes of fury.', '一块刻有古代牛头人狂怒符文的石板。'),
    ('A stone tablet covered in glowing runes of extraordinary permanence.', '一块覆满发光符文、格外经久的石板。'),
    ('A stone tablet etched with runes that pulse with barely contained rage.', '一块刻着符文、脉动着几乎无法抑制的狂怒的石板。'),
    ('A stone that seems to leech light into its polished, inky depths.', '一块似乎能把光吸进其抛光黑色深处的石头。'),
    ('A storm-touched manuscript that crackles with electrical energy, its pages alive with the fury of tempests.', '一份迸发电气能量的风暴手稿，书页上涌动着风暴的怒火。'),
    ('A strange flower that never wilts.', '一朵永不凋谢的奇异花朵。'),
    ('A strange warmth emanates from inside.', '里面散发出一股奇异的暖意。'),
    ('A strike that becomes active after parrying an opponent\'s attack.  This attack deals  weapon damage and slows their melee attack speed by  for   Awards  combo point.', '一次在招架对手攻击后激活的打击。  此攻击造成  点武器伤害，并使目标的近战攻击速度降低 ，持续   获得  点连击点。'),
    ('A strike that deals  weapon damage ( if a dagger is equipped) and increases your chance to dodge by  for   Awards  combo int:points', '一次打击，造成 点武器伤害（装备匕首时为 ），并使你的闪避几率提高 ，持续  获得 个连击 int:点'),
    ('A strip of fresh Loch Frenzy meat.', '一条新鲜的洛克狂澜鱼肉。'),
    ('A strip of meat long gone to rot. The cloying sweetness of decay numbs the senses.', '一条早已腐烂的肉条。那股甜腻的腐臭让感官都麻木了。'),
    ('A strip of muscle pulled from a diseased wolf.', '从一头染病野狼身上扯下的一条肌肉。'),
    ('A sturdy casing for explosives.', '一个结实的炸药外壳。'),
    ('A subtle glow indicates that the ring is powering up...', '一道微光显示这枚戒指正在充能……'),
    ('A swirling elixir distilled from the tainted blood of the abyssal demons. The liquid glimmers with foul magics that twist the body and soul of any foolish enough to imbibe it.', '一种由深渊恶魔污染之血蒸馏而成的旋动药剂。这液体闪烁着邪异魔法，会扭曲任何胆敢饮下之人的身心。'),
    ('A swirling sphere of elemental water.', '一个旋转的元素之水球。'),
    ('A swirling tempest surrounds the ring.', '指环周围环绕着旋转的风暴。'),
    ('A sword honed to a molten edge.', '一把磨出熔融锋刃的剑。'),
    ('A symbol of the Legion\'s power!', '军团力量的象征！'),
    ('A tantalizing pattern glows across the plant\'s stem.', '植株茎干上闪烁着诱人的纹路。'),
    ('A tarnished ring inscribed with "For P.H. from R.H with Love."', '一枚晦暗的戒指，刻着「致 P.H.，来自深爱你的 R.H.」。'),
    ('A technical manual filled with intricate blueprints, accompanied by the faint sound of ticking clockwork mechanisms.', '一本填满精细蓝图的技工手册，伴随着隐约的钟表机构滴答声。'),
    ('A terrifying, shapeless mass of horrors that fills your mind with dread.', '一团可怕而无形的恐怖之物，让你的心中充满惊惧。'),
    ('A test artifact.', '一件测试法器。'),
    ('A test token for the Currency Token system', '代币系统用的一枚测试代币。'),
    ('A testement to range over accuracy.', '专注射程而非精准的证明。'),
    ('A text filled with tactical notes and battle diagrams.', '一本写满战术笔记与战斗图解的书。'),
    ('A thin, shimmering fluid tainted with otherworldly power. The demonic elixir can imbue the drinker with great strength, but the price is a blackened soul.', '一种稀薄而闪动的液体，沾染着异界之力。这种恶魔药剂能赋予饮用者强大的力量，代价却是灵魂被染黑。'),
    ('A third test token for the Currency Token system', '货币代币系统的第三个测试代币'),
    ('A tightly wound scroll, addressed to you.', '一卷紧缠的卷轴，写给你。'),
    ('A token of Haleh\'s gratitude.', '哈蕾的感激之礼。'),
    ('A tooth still stained red at the root. Did it belong to Glotka, or perhaps one of his unexpected visitors? In any case, violence certainly visited this room.', '一颗根部仍染红的牙齿。它属于格洛特卡，还是他某位不速之客？无论如何，这间屋子确实见证过暴力。'),
    ('A torn leather satchel, its surface stiff with dried blood.', '一只撕破的皮挎包，表面因干血而发硬。'),
    ('A totem pulsing with raw elemental energy.', '一尊脉动着原始元素能量的图腾。'),
    ('A trail of messy footprints crosses the room and stops around the bed. Glotka was asleep when his "guests" arrived.', '一串凌乱的脚印穿过房间，在床边停下。格洛特卡的“客人”到来时他正在睡觉。'),
    ('A trophy earned by completing trials that can be turned in for rewards. \n\nThese can be traded to a Challenge Master for exclusive cosmetics in any capital or starting zone.', '通过完成试炼获得的奖杯，可上交换取奖励。 \n\n可在任何主城或起始区域的挑战大师处兑换专属幻化物品。'),
    ('A trophy for slaying Tabbu', '击杀塔布的战利品'),
    ('A trophy for slaying a Necro-Vrykul', '击杀一名死灵维库人的战利品'),
    ('A turnip with an extremely tough exterior, it can take hits just as well as a heroic level dungeon boss.', '一颗外皮极其坚硬的芜菁，它挨打的能力堪比英雄地下城首领。'),
    ('A twisted, decayed piece of grass.', '一段扭曲、腐烂的草。'),
    ('A valuable member of the Pa\'Troll!', '帕巨魔中的宝贵成员！'),
    ('A valuable resource.', '一种宝贵的资源。'),
    ('A variant of the Rock-Salted Pretzel created by the Fireboot sisters. It seems a bit too hot for anyone that isn\'t a Dark Iron.', '火靴姐妹制作的岩盐椒脆饼的变体。对非黑铁矮人来说似乎有点太辣了。'),
    ('A vehicle designed by top-notch hyjal engineers.', '由顶尖海加尔工程师设计的载具。'),
    ('A very large petrified leaf.', '一片巨大的石化树叶。'),
    ('A vial containing a red substance that looks strangely delicious.', '一瓶红色物质，看起来奇怪地美味。'),
    ('A vial of thick, black blood coursing with demonic energy. Mannoroth\'s cursed vitae infected the orcs and bound them to the will of the Burning Legion. This sample remains potent and volatile.', '一瓶涌动着恶魔能量的浓稠黑血。玛诺洛斯的受诅之血感染了兽人，将他们束缚于燃烧军团的意志。这份样本依旧浓烈而不稳。'),
    ('A vibrant life energy emanates from this seed.', '这颗种子散发着蓬勃的生命能量。'),
    ('A viscous, pungent sap suitable as a binder.', '一种粘稠刺鼻、可作粘合剂的树液。'),
    ('A visor set with unblinking crocolisk eyes.', '一副镶着不眨眼鳄鱼眼的面罩。'),
    ('A volatile keg of explosives covered with pictographic warnings.', '一桶画满象形警告的易爆火药。'),
    ('A vow written on blessed hide.', '写在祝圣兽皮上的誓言。'),
    ('A wand left by your trainer.', '你的训练师留下的一根魔杖。'),
    ('A wanted poster for the criminal swashbuckler known as Krelin.', '一张通缉剑客克雷林的海报。'),
    ('A water stained picture can be seen inside the locket.', '吊坠里能看到一张水渍斑斑的照片。'),
    ('A weathered artifact containing fragments of ancient knowledge. These sacred relics hold the wisdom of ages past.', '一件风化的遗物，内藏古代知识的碎片。这些神圣遗物承载着往昔岁月的智慧。'),
    ('A weathered guide marked with tracks from countless beasts.', '一本标满无数野兽足迹的破旧指南。'),
    ('A weathered shard recovered from the outer ruins of Isildien.', '一块从伊希尔迪安外围废墟中找到的破旧碎片。'),
    ('A weathered stone tablet carved with orcish war-runes that pulse with barely contained fury.', '一块风化的石板，刻着随几乎无法抑制的怒火脉动的兽人战符文。'),
    ('A weathered stone tablet carved with primitive barbarian runes that pulse with primal fury.', '一块风化的石板，刻着随原始怒火脉动的蛮族符文。'),
    ('A wooden pipe with traces of an exotic substance.', '一根残留着异域物质的木制烟斗。'),
    ('A worn bone from a troll fortunate enough to die before the cataclysm that shook the region. Those who came after mistook the murmur of the Sleeper for the seductive whispers of a loa craving adoration. The world bore the weight of their ignorance.', '一块来自幸运巨魔的磨损骨头，它在撼动此地的灾变来临前就已死去。后来者把沉睡者的低语误当作渴求崇拜的 loa 诱惑之声。世界承受了他们无知的重量。'),
    ('A worn out bag Niko used to send you the things they scavanged in the Manastorm. It\'s big enough to hold some of your own possessions.', '尼科用来寄给你法力风暴中拾得之物的旧包。它大到足够装下你自己的一些物品。'),
    ('A worn volume, believed lost, containing an account of the deeds of the Knights of the Silver Hand.', '一本被认为已失传的旧书，记载着白银之手骑士团的事迹。'),
    ('A writhing parchment covered in symbols that whisper forbidden secrets when not observed directly.', '一页扭动的羊皮纸，上面覆满的符号在不被直视时会低语禁忌的秘密。'),
    ('A writhing scroll covered in symbols that shift and change when not directly observed.', '一卷扭动的卷轴，上面覆满的符号在不被直视时会不断变化。'),
    ('A written account from the explorers of the Forgotten Mine. You can only assume this to be the same story the old man would have told, had you stayed to talk with him.', '一份来自被遗忘矿井探索者的书面记述。你只能猜测，这与那位老人当时想讲的故事是同一个。'),
    ('A written letter of initiation into the Ranger\'s Guild with orders on how to join.', '一封游侠公会的入会信，附有如何加入的指示。'),
    ('Activate Arcane Spheres.', '激活奥术宝珠。'),
    ('Activate Blessing of Holy Light', '激活圣光祝福'),
    ('Activate Molten Spheres.', '激活熔岩宝珠。'),
    ('Activate Shadow Orbs.', '激活暗影宝珠。'),
    ('Activate Spirit Healer\'s Wings.', '激活灵魂医者的翅膀。'),
    ('Activate Verdant Spheres.', '激活翠绿宝珠。'),
    ('Activate the Idol of Rage effect.', '激活怒气神像效果。'),
    ('Activate the Nightmarish effect.', '激活梦魇效果。'),
    ('Activate wings sititched by nightmare.', '激活噩梦缝制的翅膀。'),
    ('Actually, every single denizen of Azeroth is actually a Dreadlord in disguise!\nThis is a rare and exclusive item.', '其实，艾泽拉斯的每一位居民都是伪装的恐惧魔王！\n这是稀有而专属的物品。'),
    ('Adding a touch of life when it\'s dark and cold.', '在黑暗寒冷时添上一抹生气。'),
    ('Addressed to High General Brigitte Abbendis', '寄给高级将军布里吉特·阿比迪斯'),
    ('Adds a chill effect to your Blizzard spell.  This effect lowers the target\'s movement speed by   Lasts 84d.', '为你的暴风雪法术附加寒冷效果。  该效果使目标的移动速度降低  持续 84d。'),
    ('Adds a chill effect to your Blizzard spell.  This effect lowers the target\'s movement speed by   Lasts 85d.', '为你的暴风雪法术附加寒冷效果。  该效果使目标的移动速度降低  持续 85d。'),
    ('Adds a chill effect to your Blizzard spell.  This effect lowers the target\'s movement speed by   Lasts 86d.', '为你的暴风雪法术附加寒冷效果。  该效果使目标的移动速度降低  持续 86d。'),
    ('Adds another Manastorm to the world, as if it needed it.', '又给这个世界添了一场法力风暴，好像它还不够似的。'),
    ('Adventure is always better with a clucking companion!', '有只咯咯叫的伙伴陪着，冒险总是更精彩！'),
    ('Affixes your one-handed rune weapon with a rune that deflects  of all spell damage and reduces the duration of Silence effects by  (not cumulative with additional Silence duration reduction).  Modifying your rune weapon requires a Rune Forge in Ebon Hold.', '为你的单手符文武器附加一枚符文，可偏转  的法术伤害，并使沉默效果的持续时间缩短  （不与其它沉默时长缩短效果叠加）。修改符文武器需要黑锋要塞的符文熔炉。'),
    ('Affixes your one-handed rune weapon with a rune that increases Parry chance by 2% and reduces the duration of Disarm effects by   Modifying your rune weapon requires a Rune Forge in Ebon Hold.', '用一枚符文为你的单手符文武器附魔，使其招架几率提高 2%，并使缴械效果持续时间缩短   强化符文武器需要黑锋要塞中的符文熔炉。'),
    ('Affixes your rune weapon with a rune that adds 2% extra weapon damage as Fire damage or 4% versus Undead targets.  Modifying your rune weapon requires a Rune Forge in Ebon Hold.', '用一枚符文为你的符文武器附魔，使其额外造成 2% 的火焰伤害，对亡灵目标则为 4%。  强化符文武器需要黑锋要塞中的符文熔炉。'),
    ('Affixes your rune weapon with a rune that has a chance to heal you for  and increase total Strength by  for   Modifying your rune weapon requires a Rune Forge in Ebon Hold.', '用一枚符文为你的符文武器附魔，使其有几率治疗你  点生命值，并在  内使总力量提高   强化符文武器需要黑锋要塞中的符文熔炉。'),
    ('Affixes your rune weapon with a rune that has a chance to increase the damage by  for your next 2 attacks that deal Frost or Shadow damage.  Modifying your rune weapon requires a Rune Forge in Ebon Hold.', '用一枚符文为你的符文武器附魔，使其有几率使你接下来 2 次造成冰霜或暗影伤害的攻击伤害提高   强化符文武器需要黑锋要塞中的符文熔炉。'),
    ('Affixes your rune weapon with a rune that increases Defense by  and total Stamina by   Modifying your rune weapon requires a Rune Forge in Ebon Hold.', '用一枚符文为你的符文武器附魔，使其防御提高 ，总耐力提高   强化符文武器需要黑锋要塞中的符文熔炉。'),
    ('Affixes your two-handed rune weapon with a rune that deflects  of all spell damage and reduces the duration of Silence effects by   Modifying your rune weapon requires a Rune Forge in Ebon Hold.', '用一枚符文为你的双手符文武器附魔，使其偏转  的法术伤害，并使沉默效果持续时间缩短   强化符文武器需要黑锋要塞中的符文熔炉。'),
    ('Affixes your two-handed rune weapon with a rune that increases Defense by  and total Stamina by   Modifying your rune weapon requires a Rune Forge in Ebon Hold.', '用一枚符文为你的双手符文武器附魔，使其防御提高 ，总耐力提高   强化符文武器需要黑锋要塞中的符文熔炉。'),
    ('Affixes your two-handed rune weapon with a rune that increases Parry chance by 4% and reduces the duration of Disarm effects by   Modifying your rune weapon requires a Rune Forge in Ebon Hold.', '用一枚符文为你的双手符文武器附魔，使其招架几率提高 4%，并使缴械效果持续时间缩短   强化符文武器需要黑锋要塞中的符文熔炉。'),
    ('Affixes your weapon with a rune that causes 2% extra weapon damage as Frost damage and increases enemies\' vulnerability to your Frost attacks. Modifying your rune weapon requires a Rune Forge in Ebon Hold.', '用一枚符文为你的武器附魔，使其额外造成 2% 的冰霜伤害，并提高敌人对你冰霜攻击的易伤。强化符文武器需要黑锋要塞中的符文熔炉。'),
    ('After killing an opponent that yields experience or honor, gives you a  increased critical strike chance on your next Sinister Strike, Hemorrhage, Backstab, Mutilate, Ambush, or Ghostly Strike.  Lasts 43d.', '在击杀一个能提供经验或荣誉的对手后，使你下一个邪恶攻击、出血、背刺、毁伤、伏击或幽灵打击的暴击几率提高   持续 43d。'),
    ('After killing an opponent that yields experience or honor, gives you a  increased critical strike chance on your next Sinister Strike, Hemorrhage, Backstab, Mutilate, Ambush, or Ghostly Strike.  Lasts 49d.', '在击杀一个能提供经验或荣誉的对手后，使你下一个邪恶攻击、出血、背刺、毁伤、伏击或幽灵打击的暴击几率提高   持续 49d。'),
    ('After landing a non-periodic critical strike with a Fire, Frost, or Nature damage spell, you enter a Clearcasting state.  The Clearcasting state reduces the mana cost of your next  damage or healing spells by 46s1%.', '在使用火焰、冰霜或自然伤害法术造成一次非持续性的暴击后，你会进入清晰施法状态。  该状态使你接下来  次伤害或治疗法术的法力消耗降低 46s1%。'),
    ('Aged, sinewy gorilla meat.  Really only suitable for revenge.', '陈年、多筋的大猩猩肉。真的只适合用来复仇。'),
    ('Ah, the cattle of Eversong are ESPECIALLY lean and tender!', '啊，永歌森林的牛特别瘦嫩！'),
    ('Air, water, fire, or earth.', '空气、水、火或土。'),
    ('Al\'ar is Kael\'thas Sunstrider\'s precious pet phoenix that he cares for deeply. His children also serve Kael\'thas. As with all phoenixes, he is reborn from his own ashes, so adventurers wishing to take him down may have to do so more than once. . .', '奥是凯尔萨斯·逐日者珍爱的宠物凤凰，他对其关怀备至。他的子嗣也同样效忠于凯尔萨斯。如同所有凤凰一样，他从自身的灰烬中重生，因此想要击败他的冒险者或许得不止一次动手。'),
    ('Alchemists can cultivate these into ingredients at a Sanguine Workbench.\n\nObtained from herb nodes in High-Risk Tier zones.', '炼金师可在血色工作台将其培育为材料。\n\n从高风险档次区域的草药节点获得。'),
    ('All melee attacks deal  to  additional Holy damage.  When used with attacks or abilities that strike a single target, this additional Holy damage will strike up to 2 additional targets.  Lasts  this Seal\'s energy will judge an enemy, instantly causing  to  Holy damage.', '所有近战攻击额外造成  至  点神圣伤害。当与单体目标攻击或技能一同使用时，该额外神圣伤害会波及最多 2 个额外目标。持续  ，释放此圣印的能量可审判一名敌人，立即造成  至  点神圣伤害。'),
    ('All of the effort you are making is worth the repair costs.', '你付出的一切努力都值那点修理费。'),
    ('All of this fake gold should guarantee us winning the oil drilling rights!', '这么多假金子应该足以保证我们拿下石油开采权！'),
    ('All of this stuff is going to sell for bank!', '这些东西全都能卖进公会银行！'),
    ('All party or raid members within  yards lose  less casting or channeling time when damaged.  Players may only have one Aura on them per Paladin at any one time.', '码内所有小队或团队成员在受到伤害时损失的施法与引导时间减少   每名圣骑士同时只能给一个目标施加一种光环。'),
    ('All properties tested and certified by Ariden.', '所有性能均经阿里登测试认证。'),
    ('All souls reveal their nature when trusted, even when trusting is undeserved. -Diamant the Patient', '所有灵魂在被信任时都会显露本性，即使这份信任并不值得。——耐心的迪亚马特'),
    ('All that glitters is not gold.  But you can sell it for gold most of the time.', '闪光的不一定是金子。但多数时候你可以拿它换金子。'),
    ('All that remains of the former Highlord Alexandros Mograine.', '前大领主亚历山德罗斯·莫格莱尼仅剩的遗骸。'),
    ('All that remains of the hellspawn, Magtheridon.', '地狱魔犬玛瑟里顿仅剩的残骸。'),
    ('Allow the fury of the Restless King to take over you and start spewing flames when you attack. This is a cosmetic effect.', '让无眠之王的怒火接管你，攻击时喷吐火焰。这是装饰性效果。'),
    ('Allows opening of locked chests and doors.', '可以打开上锁的箱子和门。'),
    ('Allows the Druid to prowl around, but reduces your movement speed by   Lasts until cancelled.', '让德鲁伊得以潜行，但会使你的移动速度降低  持续到主动取消。'),
    ('Allows the caster to see through the target\'s eyes for', '让施法者透过目标的眼睛观察，持续'),
    ('Allows the caster to see through the target\'s eyes for   Will not work if the target is in another instance or on another continent.', '使施法者可通过目标的眼睛观察，持续  如果目标在另一个副本或另一块大陆上则无效。'),
    ('Allows the friendly target to detect lesser invisibility for', '使友方目标能侦测次级隐形，持续'),
    ('Allows the friendly target to walk across water for   Any damage will cancel the effect.', '使友方目标能够在水面上行走，持续  。任何伤害都会取消该效果。'),
    ('Allows the rogue to sneak around, but reduces your speed by   Lasts until cancelled.', '让盗贼得以潜行，但会使你的速度降低  持续到主动取消。'),
    ('Allows the rogue to vanish from sight, entering an improved stealth mode for   Also breaks movement impairing effects.', '让盗贼从视线中消失，进入强化潜行状态，持续  同时解除移动限制效果。'),
    ('Allows the target to breathe underwater for', '使目标可以在水下呼吸，持续'),
    ('Allows the target to breathe underwater for  and increases swim speed by 79s1%.][.]', '使目标能够在水中呼吸 ，并使游泳速度提高 79s1%。][.]'),
    ('Allows the wielder to pass into the Spirit Void.', '允许持有者进入灵魂虚空。'),
    ('Allows you to alter the look of your armor.', '让你可以改变护甲外观。'),
    ('Allows you to equip two-handed axes, maces and swords in one hand.  While you have a two-handed weapon equipped in one hand, your physical damage done is reduced by 52s1%.', '使你可以单手装备双手斧、锤和剑。  当你单手装备双手武器时，你造成的物理伤害降低 52s1%。'),
    ('Allows you to interact with the spirit of Kalytha.', '允许你与卡莉莎的灵魂交流。'),
    ('Allows you to obtain Cat Form in your Draft Mode.', '允许你在选秀模式中获得猎豹形态。'),
    ('Allows you to peer into the Emerald Dream...it likely won\'t last long without the Keeper\'s power though', '让你得以窥见翡翠梦境……不过若没有守护者的力量，这大概维持不了多久'),
    ('Allows you to purge your Class Tree, and reinvest.|nOnly usable by Conquest of Azeroth classes.', '可让你净化职业树并重新投点。|n仅限征服艾泽拉斯的职业使用。'),
    ('Allows you to purge your Specialization Tree, and reinvest.|nOnly usable by Conquest of Azeroth classes.', '可让你净化专精树并重新投点。|n仅限征服艾泽拉斯的职业使用。'),
    ('Allows you to resurrect yourself upon death with  health and mana.', '使你在死亡时能以  点生命值与法力值自我复活。'),
    ('Allows you to revive your character. This will fail your current trials, and allow you to continue playing as a normal hero. You only get one of these Iron souls per account.', '可让你的角色复活。这会令你当前的试炼失败，并允许你以普通英雄的身份继续游戏。每个账号只能获得一次铁魂。'),
    ('Allows you to ride ground mounts that require a riding skill of 100.', '允许你骑乘需要 100 点骑术的地面坐骑。'),
    ('Allows you to see the world for how it really is.', '让你看清这个世界的真实模样。'),
    ('Allows you to see what mundane eyes cannot perceive. The Caretakers have only entrusted this relic to you for use within Stromgarde, so it would be best not to use it beyond the keep\'s walls.', '让你看见凡眼所不能察觉之物。看守者仅将此遗物托付给你，用于激流堡城内，最好别在要塞城墙之外使用它。'),
    ('Allows your character to select primary stat.', '允许你的角色选择主属性。'),
    ('Almost seems to be staring back at you.', '几乎像在回望你。'),
    ('Already the leaves in the bag appear to be wilting. You should quickly get them to Orendil at Maestra\'s Post.', '袋中的叶子看起来已经开始枯萎了。你该尽快把它们送到麦斯特拉哨所的奥伦迪尔那里。'),
    ('Also functions as a Blacksmith Hammer!', '也可作为铁匠锤使用！'),
    ('Also used by Inscribers to create books, scrolls, and glyphs.', '也被铭文师用于制作书籍、卷轴和雕文。'),
    ('Although crusted in filth, the etched metallic disc shows no corrosion.', '尽管蒙着污垢，这枚刻纹金属圆盘却没有腐蚀。'),
    ('Although no longer charged, the battered hammerhead tells a tale of combat.', '虽然早已失去灌注，这枚残破的锤头仍诉说着战斗的故事。'),
    ('Always seem to roll 7s...', '好像总是掷出 7 点……'),
    ('Amalgam of good flesh, taken from the Moonlit Ossuary. It oozes rot and reeks of carrion. Yet somehow, it stirs the appetite of every druid around you.', '从月光骨库取来的健壮血肉混合物。它渗出腐液，散发着腐尸的恶臭，却不知怎地勾起了周围每个德鲁伊的食欲。'),
    ('Amazingly well-crafted, and emanating a faint magical glow.', '工艺惊人，还散发着微弱的魔法光芒。'),
    ('Amber Wings of Paragon', '典范琥珀之翼'),
    ('Among the papers in the document, you can see lists of names and addresses. This will be of interest to Mara.', '文件中可以看到姓名与地址的清单。玛拉会对此感兴趣。'),
    ('An aggressive fish that is relatively tasty if properly cooked. The naga and ogres in Zangarmarsh seem to use them as a food source as well.', '一种具有攻击性的鱼，若烹饪得当味道相当不错。赞加沼泽的纳迦与食人魔似乎也把它当作食物来源。'),
    ('An aggressive stance.  Critical hit chance is increased by  and all damage taken is increased by 1s2%.', '一种进攻性姿态。  爆击几率提高 ，受到的所有伤害提高 1s2%。'),
    ('An agreement between the Defias and the Venture Co.', '迪菲亚与风险投资公司之间的一份协议。'),
    ('An amulet far more intriguing than its unremarkable appearance suggests. It allows its bearer to extract samples of spiritual unrest from the tormented inhabitants of the Valley of Trials.', '一枚远比其平凡外观更有意思的护符。它能让持有者从试炼谷饱受折磨的居民身上提取精神躁动的样本。'),
    ('An ancient codex bound in bone, inscribed with necromantic secrets.', '一部以骨骼装订的古老典籍，写满了死灵法术的秘密。'),
    ('An ancient design with a silvery wing emblem.', '带有银色翅膀纹章的古老设计。'),
    ('An ancient key to a secret entrance in the Throne of Thunder.  The Shado-Pan would be interested in this.', '一把通往雷电王座秘密入口的古老钥匙。  影踪派会对此感兴趣。'),
    ('An ancient manuscript that seems to exist in multiple moments simultaneously, its text shifting through past and future.', '一份似乎同时存在于多个时刻的古老手稿，其文字在过去与未来之间变换。'),
    ('An ancient mogu artifact.', '一件古老的魔古神器。'),
    ('An ancient relic of the furbolg, now reassembled after many years.', '熊怪的一件古老遗物，时隔多年后被重新拼合。'),
    ('An ancient relic of the pre-legion Mag\'har clans.', '军团降临前玛格汉氏族的古老遗物。'),
    ('An ancient relic, incredibly valuable...', '一件极其珍贵的古老遗物……'),
    ('An ancient scroll decorated with tribal fetishes, humming with ancestral power and loa magic.', '一卷装饰着部族图腾饰物的古老卷轴，低鸣着先祖之力与洛阿魔法。'),
    ('An ancient scroll stained with blood that still appears wet after countless years.', '一卷染血的古老卷轴，历经无数年仍显得湿漉漉的。'),
    ('An ancient staff, used to bind the souls of the Inkgill to their pearls, and thus, the Mere.', '一根古老的法杖，用于将墨鳃氏族的灵魂束缚在他们的珍珠上，从而束缚整片水泽。'),
    ('An ancient stone tablet carved with glowing runes that pulse with primordial power older than civilization.', '一块刻有发光符文的远古石板，其脉动的原始之力比文明更古老。'),
    ('An ancient stone tablet detailing the origins and organization of the earliest mogu empire.', '一块古老的石碑，详述最早的魔古帝国的起源与组织。'),
    ('An ancient symbol of knowledge from Pandaria\'s history.', '潘达利亚历史中一个古老的知识象征。'),
    ('An ancient symbol of strength from Pandaria\'s history.', '潘达利亚历史中一个古老的力量象征。'),
    ('An ancient tablet carved from giant bone, inscribed with necromantic symbols that whisper of undeath.', '一块由巨骨雕成的古老石板，刻满低语着亡者之秘的死灵符号。'),
    ('An ancient tome bound in dark leather, inscribed with golden runes. The pages emanate a faint holy aura.', '一本以深色皮革装订的古老典籍，刻有金色符文。书页散发着微弱的圣光。'),
    ('An ancient, cracked troll skull.', '一个古老、开裂的巨魔头骨。'),
    ('An archaic troll coin, upon whose obverse is engraved the effigy of a primordial beast, while its reverse bears the sigil of the Awakened Guardians. Upon the lofty peaks of the mountains of Dawnrise Island, where the ruins of the ancient City of Azdalar rise, a purpose for it may yet be found.', '一枚古旧的巨魔钱币，正面刻着一只原初野兽的浮雕，背面则是觉醒守护者的印记。在黎明岛群山的峻峭之巅，古老的阿兹达拉城废墟矗立之处，或许还能为它找到用途。'),
    ('An autobiography of the great adventurer known as Khazno.', '伟大冒险者卡兹诺的自传。'),
    ('An axe that may once have been used to cut down trees.', '一把或许曾用来砍树的斧头。'),
    ('An encoded manuscript penned by a blood elf researcher.', '一位血精灵研究者书写的加密手稿。'),
    ('An engraving on the bottle reads: \'The body is merely a vessel. The claw seeks what hides within.\'', '瓶身刻字写道：“身体不过是容器。利爪所求的，隐藏在内部。”'),
    ('An enormous bone harvested from one of the great beasts on the Isle of Giants.', '一根从巨兽岛上某头巨兽身上采集的巨大骨头。'),
    ('An enormous pile of freshly-killed remains.', '一大堆刚被杀死的新鲜残骸。'),
    ('An enormous slab of meat, crackling with energy.', '一大块噼啪作响、充满能量的肉。'),
    ('An entire ecosystem is hidden within.', '里面隐藏着整个生态系统。'),
    ('An etched relic taken from the old Isildien temple.', '从旧伊希尔迪安神殿取出的刻纹遗物。'),
    ('An ethereal chart containing star maps that twinkle with actual starlight.', '一张空灵的星图，图中的星图闪烁着真正的星光。'),
    ('An ethereal merchant should know to activate this.', '一位空灵商人应该知道如何激活它。'),
    ('An ethereal scroll containing star charts that twinkle with actual starlight, warm to the touch despite its celestial coldness.', '一份空灵卷轴，其中的星图闪烁着真正的星光，尽管其 celestial 冰冷触手却温热。'),
    ('An experimental creation of Artificer Baraal, made to shield the wearer against mental compulsions.', '匠师巴拉尔的实验造物，用于护持佩戴者抵御精神控制。'),
    ('An explorer, a leader, a conqueror has earned the Grace of Gods!', '一位探险者、领袖与征服者已赢得诸神的恩典！'),
    ('An exquisite specimen of trogg engineering.  Or, it might be a rock.', '穴居人工程的精美样本。或者，它可能就是块石头。'),
    ('An exquisitely preserved mandolin, oddly sturdy despite ogre handling.', '一把保存极好的曼陀林，虽经食人魔之手却出奇坚固。'),
    ('An illegal brew so strong that it could make a tauren see elemental spirits without the need for rituals.', '一种烈度非法酿造的烈酒，能让牛头人无需仪式便看见元素之灵。'),
    ('An incomprehensible pile of dense schematics.', '一堆难以理解的密集图纸。'),
    ('An inflated kodo bladder wrapped in tough, striped zhevra hide.', '用坚韧条纹斑马皮包裹的充气科多兽膀胱。'),
    ('An inflated pig\'s bladder wrapped in tough cow leather.', '用坚韧牛皮包裹的充气猪膀胱。'),
    ('An inky cloudiness twists underneath the surface of this pearl.', '墨色的浑浊在这颗珍珠表面下翻搅。'),
    ('An instant strike that causes  weapon damage.', '一次造成  点武器伤害的瞬发打击。'),
    ('An instant weapon attack that causes  of weapon damage to up to  enemies within  yards.  The Divine Storm heals up to 3 party or raid members totaling  of the damage caused.', '一次瞬发武器攻击，对 码内最多  名敌人造成  点武器伤害。  神圣风暴最多治疗 3 名小队或团队成员，治疗总量为所造成伤害的 。'),
    ('An object of power used to sustain an Ancient Enchanting Altar. Tabetha must be a talented mage indeed to be able to use such a relic directly.', '一件用于维持古代附魔祭坛的力量之物。能直接使用这件遗物，塔贝萨必定是位极有天赋的法师。'),
    ('An obscure passage in an ancient text suggested that when Meng the Demented lost this balance, he lost his mind.', '一份古籍中的晦涩段落提到，当疯狂者孟失去这份平衡时，他也失去了理智。'),
    ('An offering to the Spider Loa, Shadra.\n\nUsed to upgrade the defenses of Shadra\'Alor.', '献给蜘蛛洛阿沙德拉的祭品。\n\n用于升级沙德拉洛的防御。'),
    ('An official document, certifying Onyxia\'s death.', '一份证明奥妮克希亚已死的官方文件。'),
    ('An official document, certifying Onyxia\'s death.\n\nBring this document to one of the following to reap your rewards.\n  - Overlord Runthak outside of Orgrimmar Bank.\n  - Major Mattingly outside of Trade District in Stormwind.\n  - Baron Revilgaz on the upper boat of Booty Bay inn.', '一份官方文件，证明奥妮克希亚的死讯。\n\n将这份文件交给以下任一人即可领取奖励。\n  - 奥格瑞玛银行外的伦萨克督军。\n  - 暴风城贸易区外的马汀利少校。\n  - 藏宝海湾旅店上层船只上的雷维尔加兹男爵。'),
    ('An outline of a pending agreement between the Blackmaw and the night elves.', '黑喉部族与暗夜精灵之间一份待定协议的纲要。'),
    ('An unexpected find.', '意外收获。'),
    ('An urgent memo regarding the escapee Lilian Voss.', '一份关于逃犯莉莉安·沃斯的紧急备忘。'),
    ('Anasterian Sunstrider was the last high elven king of Quel\'Thalas. His reign, which lasted at least three thousand years, was marked by several conflicts that threatened the continued existence of Quel\'Thalas - ending with its destruction at the hands of the evil Prince Arthas Menethil.', '安纳斯特里安·逐日者是奎尔萨拉斯的最后一位高等精灵国王。他的统治至少延续了三千年，其间历经数次威胁奎尔萨拉斯存续的冲突——最终在邪恶的阿尔萨斯·米奈希尔王子手中走向毁灭。'),
    ('Ancient Sword Excalibur', '古代剑 王者之剑'),
    ('Ancient heirloom of the Kolkar chieftains.', '柯尔卡酋长们的古老传家宝。'),
    ('Another one for the pile.', '又一件，堆一起吧。'),
    ('Apparently, chains and skulls are the new black.', '显然，锁链和骷髅才是新时尚。'),
    ('Appears to have been heavily chewed on.', '看起来被狠狠啃过。'),
    ('Appers to be.. perfectly safe.', '看起来……完全安全。'),
    ('Apply this Weapon Illusion at any Transmogrifier or Directly in your Wardrobe. Does not affect Temporary Weapon Enchantment apperances!', '在任意幻化师处或直接在衣柜中应用此武器幻象。不会影响临时武器附魔的外观！'),
    ('Arcane in the membrane... arcane in the brain!', '膜里是奥术……脑子里也是奥术！'),
    ('Arcane magic swirls within the bag, imbuing the coins with a mysterious kinetic force.', '奥术魔法在袋中翻涌，将硬币注入神秘的动能。'),
    ('Arena Spoils for the Victorious.', '胜者的竞技场战利品。'),
    ('Armor piece from a warrior of the Three Totems village. Not long ago, its wearer fell in battle against the tyrant known as Malgorm Hollowhoof.', '三图腾村一位战士的护甲。不久前，它的主人战死于与暴君玛尔戈姆·空蹄的战斗中。'),
    ('As an older stronger sibling would repeatedly say: "Why are you hitting yourself?"', '就像年长的哥哥姐姐会反复说的：「你干嘛打你自己？」'),
    ('As dark as the Pearls were when corrupted, they now shine brightly, and are slightly warm to the touch.', '它们曾如被腐化时那般黑暗，如今却闪耀着明亮光芒，摸起来还微微温热。'),
    ('As far as you can tell, the label says Squid Ink and Salmon Eye.', '就你能辨认的，标签上写着乌贼墨和鲑鱼眼。'),
    ('As good a piece as any.', '和任何一件一样好。'),
    ('As much of it as you can carry.', '能拿多少就拿多少。'),
    ('As promised, it appears to be mouth-wateringly pure.', '正如承诺的那样，看起来纯净得令人垂涎。'),
    ('As shall my love never fail, neither shall the strength of your rule.', '正如我的爱永不消退，你的统治之力也将永存。'),
    ('As the earth stills, the din quiets, and your focus sharpens, strike true. -Terrath the Steady', '当大地平息、喧嚣止歇、你的心神清明之时，便一击中的。——沉稳者泰拉兹'),
    ('As the purse is emptied, the rogue\'s heart fills.', '钱包越空，盗贼的心越满足。'),
    ('As you hold the book, whispers of horrifying mysteries tantalize your ears...', '当你捧着这本书时，关于恐怖秘辛的低语在你耳边撩拨……'),
    ('As you pull your hand away from the stone, it feels as though your spirit is sticking to it for a moment.', '当你把手从石上移开时，你的灵魂仿佛仍与它粘连了一瞬。'),
    ('Aspect of Terror', '恐惧之相'),
    ('Aspect of the Viper - Reduces the damage penalty by  of the Monkey - Reduces the damage done to you while active by  of the Hawk - Increases the attack power bonus by  of the Dragonhawk - Combines the bonuses from Aspect of the Monkey and Hawk.', '蝰蛇守护 - 使雄鹰守护的伤害惩罚降低  猴子守护 - 激活期间使你受到的伤害降低  雄鹰守护 - 使攻击强度加成提高  龙鹰守护 - 结合猴子守护与雄鹰守护的加成。'),
    ('Assume a Shadowform, increasing your Shadow damage by %, reducing all damage done to you by  and threat generated by   However, you may not cast Holy spells while in this form except Cure Disease and Abolish Disease.  Grants the periodic damage from your Shadow Word: Pain, Devouring Plague, and Vampiric Touch spells the ability to critically hit for  increased damage and grants Devouring Plague and Vampiric Touch the ability to benefit from haste.', '进入暗影形态，使你的暗影伤害提高 %，受到的所有伤害降低  ，产生的威胁值降低  。但在此形态下你无法施放神圣系法术，治疗疾病与驱除疾病除外。使你的暗影之痛、噬灵瘟疫与吸血鬼之触的周期性伤害能够暴击，暴击伤害提高  ，并使噬灵瘟疫与吸血鬼之触能够从急速中获益。'),
    ('At first glance, it looks like just another piece of scrap, but if you look closely, you can see a golden gleam inside the piece.', '乍看之下像是又一块废料，但仔细看的话，能在碎片内部看到一抹金色光泽。'),
    ('At least it still has its eyes!', '至少它的眼睛还在！'),
    ('At least it\'s better than the fungus.', '至少比那真菌好点。'),
    ('At least the Dark Irons can appreciate a good beer.', '至少黑铁矮人还懂得欣赏好啤酒。'),
    ('Attempts to cure  poison effect on the target, and  more poison effect every  seconds for', '尝试为治癒目标身上的 个中毒效果，并每 秒再治癒 个中毒效果，持续'),
    ('Attempts to remove  Enrage and  Magic effect from an enemy target.', '尝试移除敌方目标身上的  个激怒与  个魔法效果。'),
    ('Attempts to step through the shadows and reappear behind your enemy and increases movement speed by  for   The damage of your next ability is increased by  and the threat caused is reduced by   Lasts 63d.', '尝试穿越阴影，出现在敌人身后，并使移动速度提高 ，持续   你下一个技能的伤害提高 ，造成的威胁值降低   持续 63d。'),
    ('Automatically shoots the target until cancelled.  Ranged attacks fired by a Hunter all have  increased attack speed.', '自动射击目标直到取消。  猎人射出的远程攻击具有 提高的攻击速度。'),
    ('Avoid contact with eyes. Safety not guaranteed.', '避免接触眼睛。安全不予保证。'),
    ('Awarded for each unique Build Draft or Featured Build completion.\n\nThese can be traded to a Challenge Master for exclusive cosmetics.', '完成每个独特的构筑草案或精选构筑时获得。\n\n可在挑战大师处兑换专属装饰品。'),
    ('Awarded from winning the Bloodbowl. This bandage seems to consume any blood it comes in contact with, allowing it to be used multiple times.', '因赢得血碗而获得。这条绷带似乎会吸收所接触到的任何血液，因此可以多次使用。'),
    ('Awarded to victors and visitors of the Brawler\'s Guild. Use it to purchase various pristine rewards from the Quartermaster.', '授予斗士公会胜利者与访客。可用它在军需官处购买各种纯净奖励。'),
    ('Awarded to victors of the Brawler\'s Guild. Use it to purchase Rumble Cards and other world-altering items at the Brawler\'s Gold Exchange vendor.', '授予搏击俱乐部的胜利者。可在搏击金币兑换商人处用它购买乱斗卡与其他改变世界之物。'),
    ('Awarded upon the completion of a Scourge or Legion invasion.\n\nCan be redeemed for cosmetic items at an Argent Quartermaster, located within major cities.', '完成天灾或燃烧军团入侵后授予。\n\n可在主城内的银色总务官处兑换幻化物品。'),
    ('Aydreath believed himself a noble protector of nature, but he was nothing more than a common beast in the end.', '艾德瑞斯自以为是自然的崇高守护者，但到头来不过是一头普通野兽。'),
    ('Azeroth\'s Greatest Treasure', '艾泽拉斯最伟大的宝藏'),
    ('Azerothian diamonds are eternal.', '艾泽拉斯的钻石恒久远。'),
    ('Azure Pheonix Weather', '碧蓝凤凰天气'),
    ('Azzar Faire Promotional Ticket. Present this ticket at the faire gates. Don\'t be late! \n\nInvite all your friends, everyone you want! In your wildest dreams you can not imagine the marvelous surprises that await you!', '阿扎尔集市宣传门票。请在集市大门出示此票。切勿迟到！ \n\n邀上你所有的朋友，所有你想邀请的人！纵使你穷尽想象，也无法预知等待你的奇妙惊喜！'),
    ('BEARD-basted...? I meant BEER-basted, hee-hee.', '用胡子腌的……？我是说用啤酒腌的，嘿嘿。'),
    ('BEHOLD, THE DARK PORTAL. Well, a tiny version, at any rate.', '看哪，黑暗之门！嗯，是个小号的。'),
    ('Baked with love by Initiate Chao\'s Mom', '学徒赵的妈妈用爱烤制'),
    ('Bands plated with interlocking crocolisk scales.', '镶有互扣鳄鱼鳞片的护腕。'),
    ('Barbarous Osteowings', '野蛮骨翼'),
    ('Bash the target with your shield dazing them and interrupting spellcasting, which prevents any spell in that school from being cast for', '用盾牌猛击目标，使其昏迷并打断施法，阻止该系任何法术在  内施放。'),
    ('Battle plans outlining the Stormpike and Bloodfang assault upon Hillsbrad.', '概述石锤与血牙对希尔斯布莱德进攻的作战计划。'),
    ('Be careful out there Hero! Contains 10 items. Make sure you have room in your inventory!', '在外小心，英雄！内含 10 件物品。请确保背包有足够空间！'),
    ('Be careful out there Hero! Contains 15 items. Make sure you have space in your inventory!', '在外小心，英雄！内含 15 件物品。请确保背包有足够空间！'),
    ('Be careful, they bite.', '小心，它们会咬人。'),
    ('Be cautious in your daily quests.', '日常任务中请多加小心。'),
    ('Bears the Agamand Family Crest.', '带有阿加曼德家族纹章。'),
    ('Bears the Horde symbol... as drawn during the Second War.', '带有部落标志……是第二次大战时绘制的样式。'),
    ('Bears the mark of Flaskataur.', '带有弗拉斯卡托的标记。'),
    ('Bears the seal of Stormwind', '盖有暴风城印记'),
    ('Beast Mastery Tome: Aspect of the Hawk (Rank 6)', '野兽掌握宝典：雄鹰守护（等级 6）'),
    ('Beast Mastery Tome: Aspect of the Wild (Rank 2)', '野兽掌握宝典：野性守护（等级 2）'),
    ('Beast Mastery Tome: Mend Pet (Rank 7)', '兽王宝典：治疗宠物（等级 7）'),
    ('Beastcaller\'s Skull Crescent', '兽唤者的骷髅月刃'),
    ('Beautiful, yet somehow sinister...', '美丽，却又莫名阴森……'),
    ('Because bigger is better.', '因为越大越好。'),
    ('Because sometimes you just need something to chew on.', '因为有时候你就是需要点东西嚼嚼。'),
    ('Because the Upper Horn is more valuable than the Lower one. . .', '因为上角比下角更值钱……'),
    ('Become S.A.V.I.O.R the Robot.', '变身为机器人 S.A.V.I.O.R。'),
    ('Become a Stone Fist.', '化身石拳。'),
    ('Become shrouded in draconic magic, disguising you as a random Blackrock denizen. Lasts 1 hour.\n\nHowever, without proper the training, it\'s unlikely to fool anyone.', '被龙族魔法笼罩，将你伪装成一名随机的黑石居民，持续 1 小时。\n\n但若没有经过恰当训练，恐怕骗不过任何人。'),
    ('Become someone else. Lasts 30 minutes.', '变成另一个人。持续 30 分钟。'),
    ('Before the Horde\'s attack, Stromgarde\'s forces made use of crossbows like this one to pick off Syndicate forces who wandered within view of the bridge.', '在部落进攻之前，激流堡的部队曾使用这种弩狙杀那些游荡到桥头视野内的辛迪加成员。'),
    ('Begins a ritual that creates a Soulwell.  Raid members can click the Soulwell to acquire a Master Healthstone.  The Soulwell lasts for  or 25 charges.  Requires the caster and 2 additional party members to complete the ritual.  In order to participate, all players must right-click the soul portal and not move until the ritual is complete.', '开始一项仪式，创造一个灵魂之井。团队成员可点击灵魂之井获取大师级治疗石。灵魂之井持续  或 25 次充能。需要施法者与另外 2 名小队成员共同完成仪式。所有玩家必须右键点击灵魂传送门，并在仪式完成前保持不动。'),
    ('Begins a ritual that creates a refreshment table.  Raid members can click the table to acquire Conjured Mana Biscuits.  The tables lasts for  or 50 charges.  Requires the caster and 2 additional party members to complete the ritual.  In order to participate, all players must right-click the refreshment portal and not move until the ritual is complete.', '开始一项仪式，创造一张点心桌。团队成员可点击点心桌获取召唤法力饼干。点心桌持续  或 50 次充能。需要施法者与另外 2 名小队成员共同完成仪式。所有玩家必须右键点击点心传送门，并在仪式完成前保持不动。'),
    ('Begins a ritual that creates a refreshment table.  Raid members can click the table to acquire Conjured Mana Strudels.  The tables lasts for  or 50 charges.  Requires the caster and 2 additional party members to complete the ritual.  In order to participate, all players must right-click the refreshment portal and not move until the ritual is complete.', '开始一项仪式，创造一张点心桌。团队成员可点击点心桌获取召唤法力酥卷。点心桌持续  或 50 次充能。需要施法者与另外 2 名小队成员共同完成仪式。所有玩家必须右键点击点心传送门，并在仪式完成前保持不动。'),
    ('Begins a ritual that creates a summoning portal.  The summoning portal can be used by 2 party or raid members to summon a targeted party or raid member.  The ritual portal requires the caster and 2 additional party or raid members to complete.  In order to participate, all players must be out of combat and right-click the portal and not move until the ritual is complete.', '开始一项仪式，创造一个召唤传送门。小队或团队成员可通过召唤传送门召唤指定的队友。仪式传送门需要施法者与另外 2 名小队或团队成员共同完成。所有玩家必须脱离战斗并右键点击传送门，在仪式完成前保持不动。'),
    ('Begins a ritual that sacrifices a random participant\'s health to summon a doomguard. Requires the caster and 4 additional party members to complete the ritual.  In order to participate, all players must right-click the portal and not move until the ritual is complete.', '开始一项仪式，牺牲一名随机参与者的生命值以召唤末日守卫。需要施法者与另外 4 名小队成员共同完成仪式。所有玩家必须右键点击传送门，并在仪式完成前保持不动。'),
    ('Begins taming a beast to be your companion.  Your armor is reduced by  while you focus on taming the beast for 20 sec.  If you lose the beast\'s attention for any reason, the taming process will fail.  Once tamed, the beast will be very unhappy and disloyal.  Try feeding the pet immediately to make it happy.', '开始驯服一只野兽作为你的伙伴。在你专注于驯服野兽的 20 秒内，你的护甲降低  。若你因任何原因失去野兽的注意力，驯服过程将失败。驯服成功后，这只野兽会非常不悦且不忠诚。请立即喂食宠物以使其开心。'),
    ('Berries are dripping off the sides it\'s so stuffed!', '浆果都从边上溢出来了，塞得真满！'),
    ('Best Friends for Eternity - Andriel and Eldanna', '永恒挚友——安德里尔与艾尔达娜'),
    ('Best not to feed this to anything.', '最好别喂给任何东西。'),
    ('Best served cold.', '冷着上桌最好。'),
    ('Best to leave it off.', '最好关着。'),
    ('Better get these back to the coach on the double!', '快把这些送回马车那里！'),
    ('Better get these to Peak Grindstone, and fast!', '最好快点把这些送到磨石峰！'),
    ('Beware of a tall night elf with one blond boot.', '提防一个穿着单只金靴的高个子暗夜精灵。'),
    ('Bigger than your head!', '比你脑袋还大！'),
    ('Binds to this specific character only and it\'s not a vanity item. This should only be used in a safe place!', '仅与这个特定角色绑定，且不是装饰性物品。只应在安全地点使用！'),
    ('Bixy\'s secret family fuel recipe that has been passed down from one Buzzsaw to the next.', '比克西家传的秘密燃料配方，一代代 Buzzsaw 传承下来。'),
    ('Black as the night sky and shiny as the stars that fill it.', '漆黑如夜空，闪亮如夜空中繁星。'),
    ('Black smoke seeps from the center of this trap.', '黑烟从这个陷阱中心渗出。'),
    ('Blackflame Skull Crescent', '黑焰骷髅月刃'),
    ('Blade of the Crimson Landlord.', '绯红房东之刃。'),
    ('Blades of Lost Fantasy', '失落幻想之刃'),
    ('Blades of Spider Demon', '蜘蛛恶魔之刃'),
    ('Bladesworn Battle Standard', '刃誓战旗'),
    ('Blessed amalgam of flesh, moistened and empowered by the gentle touch of the moon.', '受月光轻柔触碰而滋润与强化的圣洁血肉混合体。'),
    ('Blessed by Druids, a gift for a Grove Ranger', '受德鲁伊祝福，是送给林地游侠的礼物'),
    ('Blinds the target, causing it to wander disoriented for up to   Any damage caused will remove the effect.', '致盲目标，使其迷茫游荡，最多持续  造成的任何伤害都会移除该效果。'),
    ('Blood Knight\'s Feathers', '血骑士之羽'),
    ('Blood is crusted over the end of the pick.', '镐尖上结着血痂。'),
    ('Blood, brains, and goo coat the head of the shovel.', '血、脑浆和黏糊物糊满了铲头。'),
    ('Blood-Queen\'s Blessing', '血女王之赐'),
    ('Bloodforges an item transforming it into PvP Gear.\n\nThis removes the PvE power and replace it with PvP Power.\n\nIf you are Bloodforging Heroic, Mythic, or Ascended items they will be converted into a normal Bloodforged version\n\nBe careful, this is IRREVERSIBLE.', '熔血铸造一件物品，将其转化为 PvP 装备。\n\n这会移除 PvE 属性并替换为 PvP 属性。\n\n若你熔血铸造的是英雄、神话或飞升物品，它们将被转换为普通熔血版本\n\n请小心，此操作不可逆。'),
    ('Bloodied Feathers of Fallen Val\'kyr', '陨落瓦格里的染血之羽'),
    ('Bloodstained but serviceable.', '血迹斑斑，但还能用。'),
    ('Bloody and disgusting.', '血淋淋的，令人作呕。'),
    ('Blueprints depicting devices that blend magic and machinery.', '描绘魔法与机械结合装置的蓝图。'),
